/* 150 questions from the five NPTEL "AI widget" mock papers (noc25_ee134), answer keys as given; explanations added. */
window.AIQ = [{"id": "A1-1", "wk": 1, "n": 1, "topic": "charger-arch", "type": "mcq", "text": "What does the acronym EVSE stand for in the context of electric vehicle charging?", "opts": ["Electric Vehicle Safety Equipment", "Electric Vehicle Supply Equipment", "Electronic Voltage Supply Emitter", "Energy Vehicle Service Enclosure"], "ans": [1], "exp": "EVSE = Electric Vehicle <b>Supply</b> Equipment: the charging station hardware between grid and vehicle.", "diff": "Easy", "ai": 1, "grp": "charger-arch:17264911"}, {"id": "A1-2", "wk": 1, "n": 2, "topic": "rectifier", "type": "mcq", "text": "What is the primary function of a capacitive filter when added to a diode bridge rectifier?", "opts": ["To increase the input current", "To smooth the DC output voltage by reducing ripple", "To convert AC to DC", "To limit the peaky input current"], "ans": [1], "exp": "The filter capacitor stores energy near the peaks and supplies the load in between, smoothing the DC output (at the cost of peaky input current).", "diff": "Easy", "ai": 1, "grp": "rectifier:9433929"}, {"id": "A1-3", "wk": 7, "n": 3, "topic": "bridges", "type": "mcq", "text": "What is the primary motivation for operating DC-DC converters at a high switching frequency (fsw)?", "opts": ["To increase switching losses", "To reduce the size and weight of passive components like transformers and inductors", "To simplify the control circuit", "To increase the output voltage ripple"], "ans": [1], "exp": "Higher f<sub>sw</sub> shrinks inductors, capacitors and transformers (less energy/volt-seconds per cycle), at the cost of switching loss.", "diff": "Easy", "ai": 1, "grp": "bridges:97136541"}, {"id": "A1-4", "wk": 1, "n": 4, "topic": "charger-arch", "type": "mcq", "text": "In the context of EV charging, what is the primary purpose of galvanic isolation in an isolated DC-DC converter?", "opts": ["To increase the power output", "To provide safety by electrically separating the grid from the battery", "To reduce the size of the transformer", "To improve the power factor"], "ans": [1], "exp": "Isolation (HF transformer) separates the grid from the battery for safety and also matches voltage levels.", "diff": "Easy", "ai": 1, "grp": "charger-arch:91964939"}, {"id": "A1-5", "wk": 12, "n": 5, "topic": "stations-ocpp", "type": "mcq", "text": "What does the acronym OCPP stand for in the context of EV charging stations?", "opts": ["Open Charger Point Protocol", "Open Charge Point Protocol", "Online Charging Payment Protocol", "Optimized Charge Power Protocol"], "ans": [1], "exp": "OCPP = <b>Open Charge Point Protocol</b>: EVSE ↔ central management system.", "diff": "Easy", "ai": 1, "grp": "stations-ocpp:21692550"}, {"id": "A1-6", "wk": 1, "n": 6, "topic": "charger-arch", "type": "mcq", "text": "In a standard AC charging scenario, where does the primary AC-to-DC power conversion take place?", "opts": ["Within the AC EVSE", "Within the charging cable", "Inside the vehicle's onboard charger (OBC)", "At a central management system (CMS)"], "ans": [2], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Easy", "ai": 1, "grp": "charger-arch:34163027"}, {"id": "A1-7", "wk": 2, "n": 7, "topic": "boost-pfc", "type": "mcq", "text": "In a single-phase boost PFC converter, what is the primary control variable used to regulate output voltage and achieve unity power factor?", "opts": ["Switching frequency (fsw)", "Inductance value (L)", "Duty ratio (d)", "Output capacitance (C)"], "ans": [2], "exp": "The controller adjusts the <b>duty ratio d</b> every switching period: d = 1 − |v<sub>s</sub>|/V<sub>o</sub> on average.", "diff": "Easy", "ai": 1, "grp": "boost-pfc:39326577"}, {"id": "A1-8", "wk": 9, "n": 8, "topic": "magnetics", "type": "mcq", "text": "What does the B-H curve for a magnetic material graphically represent?", "opts": ["The relationship between blocking voltage and holding current", "The relationship between core loss and temperature", "The relationship between magnetic flux density (B) and magnetic field strength (H)", "The relationship between bandwidth and harmonic distortion"], "ans": [2], "exp": "The B-H curve plots flux density B against field strength H (permeability, saturation, hysteresis).", "diff": "Easy", "ai": 1, "grp": "magnetics:75087246"}, {"id": "A1-9", "wk": 1, "n": 9, "topic": "charger-arch", "type": "mcq", "text": "What is the primary function of the rectifier stage in a DC EV charger?", "opts": ["To provide galvanic isolation", "To regulate the output current", "To convert AC power from the grid into DC power", "To communicate with the vehicle's BMS"], "ans": [2], "exp": "The front-end rectifier/PFC converts grid AC to a DC link; the isolated DC-DC stage then regulates current and provides isolation.", "diff": "Easy", "ai": 1, "grp": "charger-arch:96977269"}, {"id": "A1-10", "wk": 9, "n": 10, "topic": "dab", "type": "mcq", "text": "What is a key advantage of the Dual Active Bridge (DAB) converter compared to the Phase-Shifted Full-Bridge (PSFB) converter?", "opts": ["It requires a larger output inductor", "It is limited to lower power applications", "It inherently supports bidirectional power flow", "It has a higher risk of flux walking"], "ans": [2], "exp": "DAB has two active bridges and no output inductor, so it naturally transfers power both ways (V2G).", "diff": "Easy", "ai": 1, "grp": "dab:61145916"}, {"id": "A1-11", "wk": 1, "n": 11, "topic": "charger-arch", "type": "mcq", "text": "What is the fundamental architectural difference between an AC EV charger and a DC EV charger?", "opts": ["AC chargers use single-phase power while DC chargers use three-phase power.", "The power conversion from AC to DC happens onboard the vehicle for AC charging and off-board for DC charging.", "DC chargers use CAN communication while AC chargers use PLC communication.", "AC chargers are always low power while DC chargers are always high power."], "ans": [1], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Medium", "ai": 1, "grp": "charger-arch:34163027"}, {"id": "A1-12", "wk": 5, "n": 12, "topic": "vsc3", "type": "mcq", "text": "Why is the required output capacitance for a balanced three-phase AC-DC converter significantly smaller than for a single-phase converter of similar power?", "opts": ["The switching frequency is much higher in three-phase converters.", "The instantaneous input power in a balanced three-phase system is constant, eliminating the second-line harmonic ripple.", "Three-phase systems use a smaller modulation index.", "Three-phase systems have a higher output voltage."], "ans": [1], "exp": "p = Σ v<sub>k</sub>i<sub>k</sub>: each phase has a cos(2ωt) term, 120° apart, and they cancel → constant power → no 2f<sub>line</sub> ripple → much smaller capacitor.", "diff": "Medium", "ai": 1, "grp": "vsc3:7659941"}, {"id": "A1-13", "wk": 4, "n": 13, "topic": "dcm-flyback", "type": "mcq", "text": "What is the main advantage of operating a boost PFC converter in Discontinuous Conduction Mode (DCM)?", "opts": ["It achieves a lower Total Harmonic Distortion (THD) than CCM.", "It results in lower RMS currents in the components.", "It simplifies the control loop by eliminating the need for a multiplier block.", "It allows for a smaller inductor size for the same power level."], "ans": [2], "exp": "DCM: inductor current falls to zero every switching period; the peak follows v<sub>s</sub> automatically, so no multiplier / sine-reference block is needed (simpler control), at the price of higher peak current and THD.", "diff": "Medium", "ai": 1, "grp": "dcm-flyback:4205197"}, {"id": "A1-14", "wk": 10, "n": 14, "topic": "ac-type2", "type": "mcq", "text": "During AC Type-2 charging, how does the EV signal to the EVSE that it is ready to accept a charge?", "opts": ["By sending a high-frequency signal over the Proximity Pilot (PP) line", "By changing the duty ratio of the PWM signal on the Control Pilot (CP) line", "By changing the voltage level of the PWM signal on the Control Pilot (CP) line from +9V to +6V", "By sending a CAN message to the EVSE"], "ans": [2], "exp": "The EV closes S2, adding 1.3 kΩ in parallel; the CP positive level drops from +9 V (B) to +6 V (C). The EVSE sees +6 V and closes its contactor.", "diff": "Medium", "ai": 1, "grp": "ac-type2:22617245"}, {"id": "A1-15", "wk": 9, "n": 15, "topic": "magnetics", "type": "mcq", "text": "What is the primary reason for intentionally introducing an air gap into the core of a filter inductor?", "opts": ["To increase the inductance value for a given number of turns", "To increase the core's permeability", "To prevent core saturation by increasing its current handling capability", "To reduce the physical size of the core"], "ans": [2], "exp": "The gap stores most of the energy and lowers the effective permeability: higher saturation current, inductance set by the gap rather than µ<sub>r</sub>.", "diff": "Medium", "ai": 1, "grp": "magnetics:57947117"}, {"id": "A1-16", "wk": 11, "n": 16, "topic": "ccs2", "type": "mcq", "text": "What is the primary purpose of the Signal Level Attenuation Characterization (SLAC) procedure in CCS2 DC charging?", "opts": ["To measure the battery's state of charge", "To authenticate the user for payment", "To ensure the EV's PLC modem logically connects only with its physically connected EVSE", "To set the maximum charging current"], "ans": [2], "exp": "SLAC measures signal attenuation from every EVSE modem on the shared cable bundle so the EV joins the one it is physically plugged into (lowest attenuation).", "diff": "Medium", "ai": 1, "grp": "ccs2:3786133"}, {"id": "A1-17", "wk": 4, "n": 17, "topic": "bridgeless", "type": "mcq", "text": "What is the primary cause of Zero Crossing Distortion (ZCD) in the input current of a Totem Pole PFC converter?", "opts": ["The high switching frequency of the leading leg", "The elimination of the input diode bridge", "Delays and non-ideal synchronization of switches during the input voltage's zero crossing", "The presence of a large output capacitor"], "ans": [2], "exp": "Near the zero crossing the leg roles swap; if S1 turns on briefly while S4 is on and v<sub>s</sub> ≈ 0, the inductor sees v<sub>s</sub> − V<sub>o</sub> ≈ −V<sub>o</sub> → a steep negative current spike. Switch-timing delays at the crossing cause this zero-crossing distortion.", "diff": "Medium", "ai": 1, "grp": "bridgeless:44859638"}, {"id": "A1-18", "wk": 1, "n": 18, "topic": "rectifier", "type": "mcq", "text": "In a single-phase full-bridge rectifier with a purely resistive load, what is the characteristic of the current drawn from the AC source?", "opts": ["It is a pulsating DC current.", "It is a square wave current.", "It is sinusoidal and in phase with the input voltage.", "It is sinusoidal but lags the input voltage by 90 degrees."], "ans": [2], "exp": "With a resistive load i = v/R, so the source current is sinusoidal and in phase (unity PF); only the capacitor filter causes peaky current.", "diff": "Medium", "ai": 1, "grp": "rectifier:44107195"}, {"id": "A1-19", "wk": 12, "n": 19, "topic": "stations-ocpp", "type": "mcq", "text": "What is a primary advantage of the JSON-based implementation of OCPP (OCPP-J) over the SOAP-based implementation (OCPP-S)?", "opts": ["It uses XML for better data structure.", "It is more secure by default without TLS.", "It is more scalable and efficient due to its lightweight format and use of a single WebSocket connection.", "It requires a unique IP address for each EVSE, which simplifies networking."], "ans": [2], "exp": "OCPP-J (JSON over one persistent WebSocket) is lighter and more scalable than OCPP-S (SOAP/XML over HTTP, which needs the CMS to reach each EVSE by its own address). Many EVSEs can sit behind one router.", "diff": "Medium", "ai": 1, "grp": "stations-ocpp:78531869"}, {"id": "A1-20", "wk": 7, "n": 20, "topic": "softsw", "type": "mcq", "text": "In a half-bridge converter, what is a necessary condition to achieve Zero Voltage Switching (ZVS) turn-on for a switch?", "opts": ["The load current must be zero.", "The dead time must be long enough for parasitic capacitances to discharge the switch voltage to zero.", "The switching frequency must be below 10 kHz.", "The switch must be an IGBT instead of a MOSFET."], "ans": [1], "exp": "The dead time must be long enough for the load current to fully discharge the incoming switch's capacitance.", "diff": "Medium", "ai": 1, "grp": "softsw:63653823"}, {"id": "A1-21", "wk": 6, "n": 21, "topic": "forward", "type": "mcq", "text": "What is a major limitation of the forward converter topology that restricts its use in high-power applications?", "opts": ["It cannot provide galvanic isolation.", "It has poor core utilization and a lossy reset mechanism that risks core saturation.", "It can only operate in discontinuous conduction mode.", "It requires switches with very low voltage ratings."], "ans": [1], "exp": "The forward converter uses only one quadrant of the B-H loop (0 → B<sub>max</sub>) and needs a core-reset mechanism (often lossy) → poor core utilisation, not used at high power.", "diff": "Medium", "ai": 1, "grp": "forward:71958970"}, {"id": "A1-22", "wk": 6, "n": 22, "topic": "dq-control", "type": "mcq", "text": "In the DQ reference frame for three-phase converter control, what is the primary purpose of aligning the d-axis with the supply voltage space vector?", "opts": ["To maximize the current in the q-axis", "To make the q-component of the supply voltage (Vsq) zero, simplifying control", "To make both Vsd and Vsq non-zero", "To eliminate the need for a PLL"], "ans": [1], "exp": "With d on the voltage vector, V<sub>sq</sub> = 0: i<sub>d</sub> sets active power and i<sub>q</sub> reactive power independently.", "diff": "Medium", "ai": 1, "grp": "dq-control:23194686"}, {"id": "A1-23", "wk": 5, "n": 23, "topic": "vsc3", "type": "mcq", "text": "In a three-phase AC-DC converter, the RMS current through the capacitor (I_C_RMS) is calculated as √(I_converter_RMS_Line^2 - I_converter_avg_Line^2). What physical phenomenon does this calculation represent?", "opts": ["The total harmonic distortion of the converter current.", "The power factor of the converter.", "The separation of the total converter output current into its DC component (which flows to the load) and its AC component (which flows through the capacitor).", "The energy stored in the inductor."], "ans": [2], "exp": "The converter DC-side current = DC part (to the load) + AC part (into the capacitor): I<sub>C,rms</sub> = √(I<sub>rms</sub>² − I<sub>avg</sub>²). Lecture result: I<sub>C,rms</sub> = I<sub>s,pk</sub>√((3/π)·M·(5/4) − (9/16)M²) (as printed in the mock key).", "diff": "Hard", "ai": 1, "grp": "vsc3:29477998"}, {"id": "A1-24", "wk": 9, "n": 24, "topic": "magnetics", "type": "mcq", "text": "In the iterative design procedure for a high-frequency transformer, if the calculated minimum total loss (P_total) for a selected core is greater than the allowed total loss (P_total_allowed), what is the immediate next step?", "opts": ["Decrease the winding fill factor (Ku).", "Increase the peak AC flux density (∆B).", "Select the next bigger core size and repeat the optimization process.", "Decrease the number of turns in the primary winding."], "ans": [2], "exp": "If the minimum achievable loss of the chosen core is still above the allowed loss, pick the next bigger core and repeat.", "diff": "Hard", "ai": 1, "grp": "magnetics:16892204"}, {"id": "A1-25", "wk": 8, "n": 25, "topic": "psfb", "type": "mcq", "text": "In a Type-2 PWM (phase-shifted) full-bridge converter, what is the primary source of energy that enables ZVS for the *lagging* leg switches?", "opts": ["The energy stored in the large output filter inductor.", "The energy stored in the transformer's leakage inductance.", "The energy stored in the output capacitor.", "The energy supplied directly from the input voltage source during dead time."], "ans": [1], "exp": "Leading leg: the large output inductor (reflected) keeps the current up → ZVS easy. Lagging leg: secondary shorted by freewheeling rectifiers, only the small leakage energy ½L<sub>lkg</sub>I² is available → ZVS lost at light load.", "diff": "Hard", "ai": 1, "grp": "psfb:28167728"}, {"id": "A1-26", "wk": 11, "n": 26, "topic": "dc001-can", "type": "mcq", "text": "In the BEVC-DC001 standard, a 'Vehicle Statistic Data' message is identified by the PGN 001C00H. What is the primary function of this Parameter Group Number (PGN) within the 29-bit CAN message ID?", "opts": ["To specify the destination address of the message.", "To act as a unique identifier for the individual signal 'Final SOC'.", "To group related parameters and allow the receiving node to quickly identify the message's context.", "To set the priority of the message on the CAN bus."], "ans": [2], "exp": "The PGN identifies which parameter group (message type) the frame carries, so the receiver knows how to decode the data bytes. Priority, destination and source are separate fields of the 29-bit ID.", "diff": "Hard", "ai": 1, "grp": "dc001-can:73105198"}, {"id": "A1-27", "wk": 6, "n": 27, "topic": "dq-control", "type": "mcq", "text": "During the design of a PI controller for the inner current loop of a three-phase AC-DC converter, what is the purpose of setting the controller's zero (KIC/KPC) equal to the plant's pole (Rs/L)?", "opts": ["To increase the steady-state error of the system.", "To perform pole-zero cancellation, simplifying the system dynamics to achieve a desired bandwidth and phase margin.", "To make the controller's response slower than the plant.", "To ensure the controller only has a proportional response."], "ans": [1], "exp": "Placing the PI zero on the plant pole (R<sub>s</sub>/L) cancels it, leaving a simple first-order loop whose bandwidth is set directly by K<sub>PC</sub>/L.", "diff": "Hard", "ai": 1, "grp": "dq-control:35831618"}, {"id": "A1-28", "wk": 3, "n": 28, "topic": "pfc-stress", "type": "mcq", "text": "What is the primary reason for the large physical size of the output capacitor in a single-phase boost PFC converter operating at unity power factor?", "opts": ["The high switching frequency ripple requires a large capacitor for filtering.", "The need to store energy for the entire line cycle during grid outages.", "The presence of a significant low-frequency (double line frequency) ripple component in the output power.", "The high DC output voltage requires a physically large dielectric."], "ans": [2], "exp": "Single-phase input power = P(1 − cos 2ωt): it pulsates at 2f<sub>line</sub> while the load takes constant P, so the capacitor must absorb a low-frequency (100 Hz) energy swing → large C.", "diff": "Hard", "ai": 1, "grp": "pfc-stress:21437407"}, {"id": "A1-29", "wk": 8, "n": 29, "topic": "psfb", "type": "mcq", "text": "In the small signal model of a Phase Shifted Full Bridge (PSFB) converter, what is the significance of the 'D-loss' term?", "opts": ["It represents the conduction loss in the diodes.", "It is a constant value that simplifies the transfer function.", "It is a duty cycle loss term dependent on inductor current and input voltage, which complicates the control model.", "It represents the energy lost during dead time."], "ans": [2], "exp": "Duty loss ΔD = 4L<sub>lkg</sub>I<sub>o</sub>f<sub>s</sub>/(nV<sub>in</sub>) reduces the effective duty and depends on inductor current and input voltage; in the small-signal model its variations (d̃<sub>i</sub>, d̃<sub>v</sub>) appear as extra controlled sources added to the buck-derived model.", "diff": "Hard", "ai": 1, "grp": "psfb:46440401"}, {"id": "A1-30", "wk": 11, "n": 30, "topic": "ccs2", "type": "mcq", "text": "In the 7-layer OSI model as applied to CCS2 High-Level Communication, which layer is responsible for assigning a logical IP address to the EV and EVSE using the Stateless Address Autoconfiguration (SLAAC) procedure?", "opts": ["Physical Layer (Layer 1)", "Data Link Layer (Layer 2)", "Network Layer (Layer 3)", "Transport Layer (Layer 4)"], "ans": [2], "exp": "SLAAC (IPv6 Stateless Address Autoconfiguration) is the <b>network layer</b> step that gives EV and EVSE their IP addresses.", "diff": "Hard", "ai": 1, "grp": "ccs2:75066936"}, {"id": "A2-1", "wk": 1, "n": 1, "topic": "charger-arch", "type": "mcq", "text": "What does EVSE stand for in the context of electric vehicle charging?", "opts": ["Electric Vehicle Safety Equipment", "Electric Vehicle Supply Equipment", "Energy Voltage Supply Electronics", "Electronic Vehicle Service Engine"], "ans": [1], "exp": "EVSE = Electric Vehicle <b>Supply</b> Equipment: the charging station hardware between grid and vehicle.", "diff": "Easy", "ai": 2, "grp": "charger-arch:17264911"}, {"id": "A2-2", "wk": 5, "n": 2, "topic": "vsc3", "type": "mcq", "text": "What is the primary purpose of the DC-Link Capacitor in a three-phase AC-DC converter?", "opts": ["To increase the switching frequency of the converter.", "To provide galvanic isolation between the AC and DC sides.", "To smooth the DC voltage and absorb ripple currents.", "To control the power factor at the AC input."], "ans": [2], "exp": "The DC-link capacitor holds the DC voltage steady and absorbs the switching-frequency ripple current.", "diff": "Easy", "ai": 2, "grp": "vsc3:93312335"}, {"id": "A2-3", "wk": 7, "n": 3, "topic": "softsw", "type": "mcq", "text": "In the context of soft switching, what is Zero Voltage Switching (ZVS)?", "opts": ["A method where the current through the switch is zero before it turns on.", "A method where the voltage across the switch is driven to zero before the current begins to rise during turn-on.", "A technique to eliminate all conduction losses in a switch.", "A method where the switching frequency is reduced to zero to minimize losses."], "ans": [1], "exp": "ZVS: the switch voltage is brought to zero (body diode conducting) before its current rises at turn-on, so the turn-on loss is (ideally) zero.", "diff": "Easy", "ai": 2, "grp": "softsw:8745504"}, {"id": "A2-4", "wk": 7, "n": 4, "topic": "bridges", "type": "mcq", "text": "What is the primary motivation for operating DC-DC converters at high switching frequencies?", "opts": ["To increase the converter's output voltage.", "To reduce the size and weight of passive components like transformers and inductors.", "To decrease conduction losses in the switches.", "To simplify the control loop design."], "ans": [1], "exp": "Higher f<sub>sw</sub> shrinks inductors, capacitors and transformers (less energy/volt-seconds per cycle), at the cost of switching loss.", "diff": "Easy", "ai": 2, "grp": "bridges:97136541"}, {"id": "A2-5", "wk": 1, "n": 5, "topic": "rectifier", "type": "mcq", "text": "What is the characteristic waveform of the input current drawn from the AC source by a diode bridge rectifier with a capacitive filter?", "opts": ["A pure sine wave in phase with the voltage.", "A square wave with high harmonic content.", "A triangular waveform synchronized with the voltage peaks.", "Sharp, narrow pulses, described as \"peaky\"."], "ans": [3], "exp": "The filter capacitor stores energy near the peaks and supplies the load in between, smoothing the DC output (at the cost of peaky input current).", "diff": "Easy", "ai": 2, "grp": "rectifier:9433929"}, {"id": "A2-6", "wk": 7, "n": 6, "topic": "bridges", "type": "mcq", "text": "What is a key advantage of a full-bridge DC-DC converter regarding switch voltage stress when compared to a push-pull converter?", "opts": ["The switches in a full-bridge converter block half the input voltage (Vin/2).", "The switches in a full-bridge converter only need to block the input voltage (Vin).", "The switches in a full-bridge converter block twice the input voltage (2Vin).", "The switches in a full-bridge converter experience zero voltage stress."], "ans": [1], "exp": "Full-bridge switches block V<sub>in</sub>; push-pull switches block 2V<sub>in</sub>.", "diff": "Easy", "ai": 2, "grp": "bridges:95775696"}, {"id": "A2-7", "wk": 6, "n": 7, "topic": "dq-control", "type": "mcq", "text": "What is the primary advantage of using the DQ rotating reference frame for controlling three-phase AC-DC converters?", "opts": ["It increases the switching frequency of the converter.", "It transforms AC quantities into DC quantities under steady-state, simplifying controller design.", "It eliminates the need for an output capacitor.", "It physically decouples the three phases of the AC source."], "ans": [1], "exp": "In the synchronous dq frame balanced AC quantities become DC in steady state, so simple PI controllers give zero steady-state error.", "diff": "Easy", "ai": 2, "grp": "dq-control:41921964"}, {"id": "A2-8", "wk": 12, "n": 8, "topic": "stations-ocpp", "type": "mcq", "text": "What is the primary purpose of the Open Charge Point Protocol (OCPP)?", "opts": ["To standardize the physical shape of charging connectors.", "To define the voltage and power levels for DC fast charging.", "To enable interoperability and standardized communication between EVSEs and Central Management Systems (CMS).", "To regulate the price of electricity at public charging stations."], "ans": [2], "exp": "OCPP standardises EVSE ↔ CMS communication so any charger works with any back-end (interoperability).", "diff": "Easy", "ai": 2, "grp": "stations-ocpp:14011010"}, {"id": "A2-9", "wk": 5, "n": 9, "topic": "pwm", "type": "mcq", "text": "In Sinusoidal Pulse Width Modulation (SPWM), what parameter directly controls the amplitude of the fundamental component of the output voltage?", "opts": ["The carrier frequency (fc).", "The DC link voltage (Vdc).", "The modulation index (m).", "The dead time."], "ans": [2], "exp": "m = V̂<sub>modulating</sub>/V̂<sub>carrier</sub>; the fundamental output amplitude is m·V<sub>dc</sub>/2 (linear range), so m controls it.", "diff": "Easy", "ai": 2, "grp": "pwm:35327372"}, {"id": "A2-10", "wk": 1, "n": 10, "topic": "charger-arch", "type": "mcq", "text": "In a DC charging scenario, where does the AC-to-DC power conversion take place?", "opts": ["Inside the vehicle's onboard charger.", "Within the vehicle's Battery Management System (BMS).", "Outside the vehicle, within the DC EVSE (off-board charger).", "At the grid substation before reaching the charging station."], "ans": [2], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Easy", "ai": 2, "grp": "charger-arch:34163027"}, {"id": "A2-11", "wk": 1, "n": 11, "topic": "charger-arch", "type": "mcq", "text": "What is the primary difference between AC and DC charging in terms of where the power conversion from AC to DC occurs?", "opts": ["In AC charging it happens in the EVSE, while in DC charging it happens inside the vehicle.", "Power conversion happens inside the vehicle for both AC and DC charging.", "In AC charging it happens inside the vehicle's onboard charger, while in DC charging it happens within the EVSE.", "Power conversion is not needed for DC charging."], "ans": [2], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Medium", "ai": 2, "grp": "charger-arch:34163027"}, {"id": "A2-12", "wk": 3, "n": 12, "topic": "pfc-stress", "type": "mcq", "text": "According to the energy equivalence principle, how is the minimum required DC-link capacitance (C_min) determined?", "opts": ["It is directly proportional to the nominal DC voltage (V_0) and voltage ripple (∆V_0).", "It is inversely proportional to the maximum power variation (∆P_max) and response time (T_d).", "It is calculated as (∆P_max * T_d) / (2 * V_0 * ∆V_0).", "It is based solely on the RMS current flowing through the capacitor."], "ans": [2], "exp": "Energy equivalence: ½C[(V<sub>o</sub>+ΔV<sub>o</sub>)² − (V<sub>o</sub>−ΔV<sub>o</sub>)²] = 2CV<sub>o</sub>ΔV<sub>o</sub> = ΔP<sub>max</sub>·T<sub>d</sub> → C<sub>min</sub> = ΔP<sub>max</sub>T<sub>d</sub>/(2V<sub>o</sub>ΔV<sub>o</sub>).", "diff": "Medium", "ai": 2, "grp": "pfc-stress:94655142"}, {"id": "A2-13", "wk": 7, "n": 13, "topic": "softsw", "type": "mcq", "text": "In a conventional half-bridge converter with a constant inductive load, what factor determines which of the two switches achieves ZVS turn-on?", "opts": ["The value of the DC input voltage (V_in).", "The switching frequency (F_sw).", "The direction of the load current (I0).", "The length of the dead time."], "ans": [2], "exp": "The load-current direction decides which switch's capacitance gets discharged during the dead time, i.e. which switch gets ZVS.", "diff": "Medium", "ai": 2, "grp": "softsw:97243843"}, {"id": "A2-14", "wk": 9, "n": 14, "topic": "magnetics", "type": "mcq", "text": "In transformer design, what is the relationship between the Peak AC Flux Density (deltaB) and the two primary loss components?", "opts": ["Both core loss and copper loss increase as deltaB increases.", "Core loss increases with deltaB, while copper loss decreases with deltaB.", "Both core loss and copper loss decrease as deltaB increases.", "Core loss decreases with deltaB, while copper loss increases with deltaB."], "ans": [1], "exp": "Core loss ∝ ΔB<sup>β</sup> (rises); copper loss ∝ 1/ΔB² (fewer turns needed for larger ΔB, so it falls). Their sum has a minimum at the optimal ΔB.", "diff": "Medium", "ai": 2, "grp": "magnetics:23443473"}, {"id": "A2-15", "wk": 9, "n": 15, "topic": "magnetics", "type": "mcq", "text": "What is the primary reason for introducing an air gap into the core of a filter inductor?", "opts": ["To increase the inductance value for the same number of turns.", "To reduce the physical size and weight of the core.", "To increase the inductor's saturation current capability.", "To eliminate all copper losses in the winding."], "ans": [2], "exp": "The gap stores most of the energy and lowers the effective permeability: higher saturation current, inductance set by the gap rather than µ<sub>r</sub>.", "diff": "Medium", "ai": 2, "grp": "magnetics:57947117"}, {"id": "A2-16", "wk": 9, "n": 16, "topic": "magnetics", "type": "mcq", "text": "According to the Empirical Steinmetz Formula, how does eddy current loss generally relate to operating frequency (f) and peak AC flux density (∆B)?", "opts": ["It is proportional to f and ∆B.", "It is proportional to f² and ∆B².", "It is inversely proportional to f and ∆B.", "It is proportional to f and ∆B²."], "ans": [1], "exp": "Eddy-current loss ∝ f²·ΔB² (hysteresis ∝ f·ΔB<sup>β</sup>).", "diff": "Medium", "ai": 2, "grp": "magnetics:26026628"}, {"id": "A2-17", "wk": 11, "n": 17, "topic": "ccs2", "type": "mcq", "text": "In the CCS2 protocol, what is the role of the EVSE processing field within response messages like ChargeParameterDiscoveryRes?", "opts": ["It indicates the total processing time taken by the EVSE.", "It signals whether the EVSE is still determining parameters ('ongoing') or has completed the task ('finished').", "It specifies the CPU load of the Supply Equipment Communication Controller (SECC).", "It provides an error code if the processing fails."], "ans": [1], "exp": "EVSEProcessing = Ongoing / Finished: tells the EV whether the EVSE is still working on the request (EV repeats the request) or is done.", "diff": "Medium", "ai": 2, "grp": "ccs2:8790483"}, {"id": "A2-18", "wk": 3, "n": 18, "topic": "pfc-stress", "type": "mcq", "text": "What is the primary cause of the \"double line frequency ripple\" on the output capacitor of a single-phase boost PFC converter operating at unity power factor?", "opts": ["The high-frequency switching of the boost converter's main switch.", "The interaction between the input power, which has a DC and a 2ωt component, and the constant power drawn by the load.", "The reverse recovery characteristics of the rectifier diodes.", "The parasitic inductance of the circuit wiring."], "ans": [1], "exp": "Single-phase input power = P(1 − cos 2ωt): it pulsates at 2f<sub>line</sub> while the load takes constant P, so the capacitor must absorb a low-frequency (100 Hz) energy swing → large C.", "diff": "Medium", "ai": 2, "grp": "pfc-stress:21437407"}, {"id": "A2-19", "wk": 9, "n": 19, "topic": "magnetics", "type": "mcq", "text": "Why is a high-frequency transformer preferred over a low-frequency (50/60 Hz) transformer for providing galvanic isolation in an EVSE?", "opts": ["Low-frequency transformers cannot provide sufficient galvanic isolation.", "High-frequency operation allows for a significantly smaller and lighter transformer core for the same power level.", "High-frequency transformers have lower core losses at the same flux density.", "Low-frequency transformers are incompatible with DC-DC converter topologies."], "ans": [1], "exp": "Higher frequency → less volt-seconds per cycle → smaller core area for the same ΔB, so the transformer is far smaller and lighter.", "diff": "Medium", "ai": 2, "grp": "magnetics:27518569"}, {"id": "A2-20", "wk": 12, "n": 20, "topic": "stations-ocpp", "type": "mcq", "text": "What is the key advantage of using a JSON/WebSocket-based OCPP implementation over a SOAP/XML-based one regarding scalability?", "opts": ["JSON messages are encrypted by default, while SOAP messages are not.", "SOAP requires a dedicated physical wire for each EVSE.", "WebSockets allow multiple EVSEs to communicate over a single persistent connection without needing unique public IP addresses for each.", "JSON is only compatible with high-power DC chargers, which are more scalable."], "ans": [2], "exp": "OCPP-J (JSON over one persistent WebSocket) is lighter and more scalable than OCPP-S (SOAP/XML over HTTP, which needs the CMS to reach each EVSE by its own address). Many EVSEs can sit behind one router.", "diff": "Medium", "ai": 2, "grp": "stations-ocpp:78531869"}, {"id": "A2-21", "wk": 4, "n": 21, "topic": "bridgeless", "type": "mcq", "text": "What is the most significant advantage of the Totem Pole PFC converter over the standard bridgeless PFC converter?", "opts": ["It uses fewer active switches.", "It completely eliminates the need for an inductor.", "Its diodes (D1, D2) switch at the low line frequency, drastically reducing reverse recovery losses.", "It can operate without a closed-loop control system."], "ans": [2], "exp": "In the totem pole the line-frequency leg (diodes or slow switches) switches at 50 Hz, so diode reverse-recovery loss is negligible; the fast leg can use GaN/SiC.", "diff": "Medium", "ai": 2, "grp": "bridgeless:73975299"}, {"id": "A2-22", "wk": 8, "n": 22, "topic": "psfb", "type": "mcq", "text": "What is the critical condition that must be met to achieve Zero Voltage Switching (ZVS) turn-on for the leading leg switches in a PSFB converter?", "opts": ["The dead time must be exactly zero.", "The leakage inductance must be minimized to zero.", "The dead time must be greater than the time required for the primary current to discharge the switch's output capacitance (e.g., &gt; 2C*Vin / (N*I0)).", "The switching frequency must be lower than the line frequency."], "ans": [2], "exp": "Leading-leg ZVS: the dead time must last longer than the time the (reflected) load current needs to charge/discharge the two switch capacitances: t<sub>d</sub> &gt; 2C·V<sub>in</sub>/(n·I<sub>o</sub>).", "diff": "Medium", "ai": 2, "grp": "psfb:29080228"}, {"id": "A2-23", "wk": 5, "n": 23, "topic": "vsc3", "type": "mcq", "text": "Why is the simplified power balance approach, which works for single-phase converters, inadequate for accurately sizing the DC-link capacitor in a three-phase AC-DC converter?", "opts": ["Because three-phase converters do not require a DC-link capacitor.", "Because the power in a three-phase system is always zero.", "Because it neglects the high-frequency switching harmonics which are the primary cause of capacitor ripple current in a balanced three-phase system.", "Because three-phase converters operate at a much lower voltage."], "ans": [2], "exp": "In a balanced 3-φ converter the power balance gives no low-frequency ripple, so the capacitor current is set by switching-frequency harmonics; the capacitor must be sized from its RMS ripple current instead.", "diff": "Hard", "ai": 2, "grp": "vsc3:38181018"}, {"id": "A2-24", "wk": 12, "n": 24, "topic": "stations-ocpp", "type": "mcq", "text": "According to the lecture, what is the correct structure of a JSON-based OCPP 1.6J \"Boot Notification Request\" message?", "opts": ["{\"Action\": \"BootNotification\", \"Payload\": {\"vendor\": \"X\", \"model\": \"Y\"}}", "[2, \"unique_id\", \"BootNotification\", {\"chargePointVendor\": \"X\", \"chargePointModel\": \"Y\"}]", "&lt;BootNotification&gt;&lt;vendor&gt;X&lt;/vendor&gt;&lt;model&gt;Y&lt;/model&gt;&lt;/BootNotification&gt;", "[\"BootNotification\", \"unique_id\", 2, {\"chargePointVendor\": \"X\", \"chargePointModel\": \"Y\"}]"], "ans": [1], "exp": "OCPP-J CALL = [2, uniqueId, \"Action\", {payload}]: the message type number comes first, then the unique ID, then the action name.", "diff": "Hard", "ai": 2, "grp": "stations-ocpp:77119758"}, {"id": "A2-25", "wk": 10, "n": 25, "topic": "ac-type2", "type": "mcq", "text": "During an AC Type-2 charging sequence, how does the EVSE detect that the EV is ready for charging, prompting the transition to State C2?", "opts": ["The EV sends a high-level communication message over the CAN bus.", "The EVSE detects a change in the Proximity Pilot (PP) pin resistance.", "The EV closes its internal S2 switch, which changes the voltage divider on the Control Pilot (CP) line, causing the positive peak voltage to drop from +9V to +6V.", "The EVSE measures an increase in the PWM signal's duty ratio to above 85%."], "ans": [2], "exp": "The EV closes S2, adding 1.3 kΩ in parallel; the CP positive level drops from +9 V (B) to +6 V (C). The EVSE sees +6 V and closes its contactor.", "diff": "Hard", "ai": 2, "grp": "ac-type2:22617245"}, {"id": "A2-26", "wk": 11, "n": 26, "topic": "ccs2", "type": "mcq", "text": "During the CCS2 charging sequence, what specific mechanism prevents a large inrush current when the EV closes its contactor switch?", "opts": ["The EVSE limits the current to 2A and matches its output voltage to the battery voltage within a 20V tolerance during the pre-charge phase.", "The EV uses a large internal resistor to absorb the initial current surge.", "The charger plug is not fully locked until the voltages are equalized.", "The high-level communication protocol negotiates a zero-current start."], "ans": [0], "exp": "Pre-charge: EVSE raises its output to the battery voltage with current limited to 2 A; the EV closes its contactors only when the difference is below 20 V, so no inrush.", "diff": "Hard", "ai": 2, "grp": "ccs2:74092662"}, {"id": "A2-27", "wk": 6, "n": 27, "topic": "dq-control", "type": "mcq", "text": "In the design of the inner current loop for a three-phase AC-DC converter, what is the primary purpose of using pole-zero cancellation in the PI controller design?", "opts": ["To increase the overall gain of the system to infinity.", "To cancel the pole of the plant (L-Rs impedance), simplifying the system dynamics and making controller gain calculation more straightforward.", "To eliminate the need for a current sensor.", "To force the converter to operate in discontinuous conduction mode."], "ans": [1], "exp": "Placing the PI zero on the plant pole (R<sub>s</sub>/L) cancels it, leaving a simple first-order loop whose bandwidth is set directly by K<sub>PC</sub>/L.", "diff": "Hard", "ai": 2, "grp": "dq-control:35831618"}, {"id": "A2-28", "wk": 4, "n": 28, "topic": "bridgeless", "type": "mcq", "text": "As described in the lecture, what is the specific mechanism that causes a negative current spike during the zero-crossing transition in a Totem Pole PFC converter?", "opts": ["The output capacitor discharges back into the grid.", "The body diodes of the low-frequency switches fail to conduct.", "When S4 is on and vs is near zero, the brief turn-on of S1 applies a large negative voltage (vs - Vo ≈ -Vo) across the inductor, causing a steep negative current slope.", "The control loop overcompensates by demanding a large negative current to maintain power factor."], "ans": [2], "exp": "Near the zero crossing the leg roles swap; if S1 turns on briefly while S4 is on and v<sub>s</sub> ≈ 0, the inductor sees v<sub>s</sub> − V<sub>o</sub> ≈ −V<sub>o</sub> → a steep negative current spike. Switch-timing delays at the crossing cause this zero-crossing distortion.", "diff": "Hard", "ai": 2, "grp": "bridgeless:44859638"}, {"id": "A2-29", "wk": 9, "n": 29, "topic": "magnetics", "type": "mcq", "text": "Explain the two-level optimization strategy for minimizing total losses in a high-frequency transformer design.", "opts": ["First, optimize the core material for low loss, then optimize the wire material.", "First, minimize core loss by choosing a low ∆B, then minimize copper loss by choosing a large wire.", "First, optimize the window area allocation (γ_j) to minimize total copper loss, then optimize the peak flux density (∆B) to minimize the sum of core and copper losses.", "First, optimize the switching frequency for minimum loss, then optimize the turns ratio."], "ans": [2], "exp": "Level 1: split the window area between windings (γ<sub>j</sub>) to minimise total copper loss. Level 2: choose ΔB to minimise core + copper loss.", "diff": "Hard", "ai": 2, "grp": "magnetics:44328294"}, {"id": "A2-30", "wk": 3, "n": 30, "topic": "pfc-control", "type": "mcq", "text": "According to the lecture, what are the three main design criteria for the inner current loop controller (Cc(s)) in a single-phase boost PFC converter?", "opts": ["Low DC gain, bandwidth equal to switching frequency, and zero phase margin.", "High gain at twice the line frequency (2fs), bandwidth significantly less than switching frequency (fsw), and sufficient phase/gain margins.", "High gain at the switching frequency, bandwidth equal to the line frequency, and a gain margin of zero.", "Low gain at all frequencies, bandwidth greater than switching frequency, and a phase margin of 90 degrees."], "ans": [1], "exp": "Current loop criteria: high gain at 2f<sub>line</sub> so i<sub>L</sub> tracks the 100 Hz rectified-sine reference; bandwidth well below f<sub>sw</sub>; adequate phase/gain margins.", "diff": "Hard", "ai": 2, "grp": "pfc-control:26955929"}, {"id": "A3-1", "wk": 1, "n": 1, "topic": "charger-arch", "type": "mcq", "text": "In the context of EV charging, what does EVSE stand for?", "opts": ["Electric Vehicle Safety Equipment", "Electric Vehicle Supply Equipment", "Energy Voltage Standardization Entity", "Electronic Vehicle Service Engine"], "ans": [1], "exp": "EVSE = Electric Vehicle <b>Supply</b> Equipment: the charging station hardware between grid and vehicle.", "diff": "Easy", "ai": 3, "grp": "charger-arch:17264911"}, {"id": "A3-2", "wk": 1, "n": 2, "topic": "charger-arch", "type": "mcq", "text": "What is the primary safety function of an isolated DC-DC converter in an EV charger?", "opts": ["To correct the power factor", "To provide galvanic isolation between the grid and the battery", "To reduce the size of the transformer", "To increase the switching frequency"], "ans": [1], "exp": "Isolation (HF transformer) separates the grid from the battery for safety and also matches voltage levels.", "diff": "Easy", "ai": 3, "grp": "charger-arch:91964939"}, {"id": "A3-3", "wk": 7, "n": 3, "topic": "softsw", "type": "mcq", "text": "What is Zero Voltage Switching (ZVS)?", "opts": ["A technique where the current through a switch is zero before it turns on.", "A technique where the voltage across a switch is zero before it turns on.", "A technique where the switching frequency is reduced to zero.", "A technique where the dead time is set to zero."], "ans": [1], "exp": "ZVS: the switch voltage is brought to zero (body diode conducting) before its current rises at turn-on, so the turn-on loss is (ideally) zero.", "diff": "Easy", "ai": 3, "grp": "softsw:8745504"}, {"id": "A3-4", "wk": 12, "n": 4, "topic": "stations-ocpp", "type": "mcq", "text": "What is the primary purpose of the Open Charge Point Protocol (OCPP)?", "opts": ["To define the physical dimensions of charging connectors.", "To ensure interoperability between EVSEs and Central Management Systems (CMS).", "To regulate the maximum power output of a charging station.", "To manage the battery's state of health during charging."], "ans": [1], "exp": "OCPP standardises EVSE ↔ CMS communication so any charger works with any back-end (interoperability).", "diff": "Easy", "ai": 3, "grp": "stations-ocpp:14011010"}, {"id": "A3-5", "wk": 5, "n": 5, "topic": "pwm", "type": "mcq", "text": "In Pulse Width Modulation (PWM), what is the 'modulation index (m)'?", "opts": ["The ratio of the carrier frequency to the modulating frequency.", "The ratio of the DC link voltage to the output voltage.", "The ratio of the peak amplitude of the modulating signal to the peak amplitude of the carrier signal.", "The total on-time of a switch in one cycle."], "ans": [2], "exp": "m = V̂<sub>modulating</sub>/V̂<sub>carrier</sub>; the fundamental output amplitude is m·V<sub>dc</sub>/2 (linear range), so m controls it.", "diff": "Easy", "ai": 3, "grp": "pwm:35327372"}, {"id": "A3-6", "wk": 4, "n": 6, "topic": "bridgeless", "type": "mcq", "text": "What is the main advantage of a bridgeless PFC converter over a conventional boost PFC converter?", "opts": ["It operates at a lower switching frequency.", "It requires a larger inductor.", "It has lower conduction losses due to fewer conducting devices.", "It eliminates the need for an output capacitor."], "ans": [2], "exp": "Bridgeless removes the diode bridge: fewer devices in the current path → lower conduction losses.", "diff": "Easy", "ai": 3, "grp": "bridgeless:18292018"}, {"id": "A3-7", "wk": 4, "n": 7, "topic": "dcm-flyback", "type": "mcq", "text": "What is the defining characteristic of Discontinuous Conduction Mode (DCM) in a PFC converter?", "opts": ["The output voltage ripple is zero.", "The inductor current falls to zero during each switching cycle.", "The switching frequency is variable.", "The power factor is always less than 0.9."], "ans": [1], "exp": "DCM: inductor current falls to zero every switching period; the peak follows v<sub>s</sub> automatically, so no multiplier / sine-reference block is needed (simpler control), at the price of higher peak current and THD.", "diff": "Easy", "ai": 3, "grp": "dcm-flyback:4205197"}, {"id": "A3-8", "wk": 11, "n": 8, "topic": "dc001-can", "type": "mcq", "text": "What type of communication is exclusively used for data exchange between the EV and EVSE in the BEVC-DC001 standard?", "opts": ["Power Line Communication (PLC)", "Pulse Width Modulation (PWM)", "Controller Area Network (CAN) communication", "Wi-Fi communication"], "ans": [2], "exp": "BEVC-DC001 (like GB/T 27930) uses <b>CAN</b> between the EV (BMS) and the charger.", "diff": "Easy", "ai": 3, "grp": "dc001-can:89787655"}, {"id": "A3-9", "wk": 1, "n": 9, "topic": "charger-arch", "type": "mcq", "text": "What is the primary architectural difference between an AC EV charger and a DC EV charger?", "opts": ["The location of the Battery Management System (BMS).", "The type of communication protocol used.", "The location of the main power conversion unit (AC-DC).", "The physical connector type used."], "ans": [2], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Easy", "ai": 3, "grp": "charger-arch:34163027"}, {"id": "A3-10", "wk": 1, "n": 10, "topic": "rectifier", "type": "mcq", "text": "What does the 'Peak Repetitive Reverse Voltage (VRRM)' rating of a diode signify?", "opts": ["The maximum forward voltage it can handle.", "The maximum average current it can conduct.", "The maximum instantaneous reverse voltage it can withstand repeatedly.", "The energy it can absorb during a short pulse."], "ans": [2], "exp": "V<sub>RRM</sub> = the maximum reverse voltage the diode can block repetitively (each cycle).", "diff": "Easy", "ai": 3, "grp": "rectifier:36143941"}, {"id": "A3-11", "wk": 1, "n": 11, "topic": "rectifier", "type": "mcq", "text": "For a single-phase full-bridge rectifier with a purely resistive load, what is the characteristic of the current drawn from the AC source?", "opts": ["It is a pulsating DC current.", "It has a high Total Harmonic Distortion (THD).", "It is sinusoidal and in phase with the input voltage.", "It flows only during the positive half-cycle of the input voltage."], "ans": [2], "exp": "With a resistive load i = v/R, so the source current is sinusoidal and in phase (unity PF); only the capacitor filter causes peaky current.", "diff": "Medium", "ai": 3, "grp": "rectifier:44107195"}, {"id": "A3-12", "wk": 3, "n": 12, "topic": "pfc-stress", "type": "mcq", "text": "What is the primary cause of the large output capacitor size required in single-phase boost PFC converters?", "opts": ["The high switching frequency ripple.", "The need to store energy for the entire charging session.", "The presence of a second-line harmonic ripple at twice the line frequency.", "The high peak reverse voltage across the capacitor."], "ans": [2], "exp": "Single-phase input power = P(1 − cos 2ωt): it pulsates at 2f<sub>line</sub> while the load takes constant P, so the capacitor must absorb a low-frequency (100 Hz) energy swing → large C.", "diff": "Medium", "ai": 3, "grp": "pfc-stress:21437407"}, {"id": "A3-13", "wk": 7, "n": 13, "topic": "bridges", "type": "mcq", "text": "What is a key advantage of the full-bridge DC-DC converter regarding its output filter components?", "opts": ["The output ripple frequency is the same as the switching frequency (fsw).", "It does not require an output inductor.", "The output ripple frequency is twice the switching frequency (2fsw), allowing for smaller components.", "The output voltage has no ripple, eliminating the need for a capacitor."], "ans": [2], "exp": "The secondary rectifier makes the output inductor see the same pulse every half switching period, so the ripple is at 2f<sub>sw</sub> → smaller L and C.", "diff": "Medium", "ai": 3, "grp": "bridges:90890863"}, {"id": "A3-14", "wk": 10, "n": 14, "topic": "ac-type2", "type": "mcq", "text": "In AC Type-2 charging, how does the EV signal to the EVSE that it is ready for charging?", "opts": ["By sending a high-frequency signal over the PP line.", "By changing the duty ratio of the PWM signal on the CP line.", "By changing the voltage level of the PWM signal on the CP line (e.g., from +9V to +6V).", "By sending a CAN message to the EVSE."], "ans": [2], "exp": "The EV closes S2, adding 1.3 kΩ in parallel; the CP positive level drops from +9 V (B) to +6 V (C). The EVSE sees +6 V and closes its contactor.", "diff": "Medium", "ai": 3, "grp": "ac-type2:22617245"}, {"id": "A3-15", "wk": 4, "n": 15, "topic": "bridgeless", "type": "mcq", "text": "What is the primary cause of zero-crossing distortion (ZCD) in a Totem Pole PFC converter?", "opts": ["The use of a large output capacitor.", "The high switching frequency of the main leg.", "The elimination of the input diode bridge.", "Delays and synchronization issues in switch transitions near the voltage zero crossing."], "ans": [3], "exp": "Near the zero crossing the leg roles swap; if S1 turns on briefly while S4 is on and v<sub>s</sub> ≈ 0, the inductor sees v<sub>s</sub> − V<sub>o</sub> ≈ −V<sub>o</sub> → a steep negative current spike. Switch-timing delays at the crossing cause this zero-crossing distortion.", "diff": "Medium", "ai": 3, "grp": "bridgeless:44859638"}, {"id": "A3-16", "wk": 11, "n": 16, "topic": "ccs2", "type": "mcq", "text": "What is the purpose of the pre-charging stage in the DC CCS2 charging sequence?", "opts": ["To verify the compatibility of the communication protocols.", "To gradually raise the EVSE output voltage to match the EV battery voltage, preventing large inrush currents.", "To perform an isolation check on the charging cable.", "To lock the connector in place before high power is applied."], "ans": [1], "exp": "Pre-charge: EVSE raises its output to the battery voltage with current limited to 2 A; the EV closes its contactors only when the difference is below 20 V, so no inrush.", "diff": "Medium", "ai": 3, "grp": "ccs2:74092662"}, {"id": "A3-17", "wk": 12, "n": 17, "topic": "stations-ocpp", "type": "mcq", "text": "Why is the JSON-based implementation of OCPP generally preferred over the SOAP-based implementation?", "opts": ["JSON uses XML for data representation, which is more robust.", "JSON with WebSockets is more lightweight, faster, and scalable.", "SOAP does not support security protocols.", "SOAP requires a physical connection for each EVSE, while JSON is wireless."], "ans": [1], "exp": "OCPP-J (JSON over one persistent WebSocket) is lighter and more scalable than OCPP-S (SOAP/XML over HTTP, which needs the CMS to reach each EVSE by its own address). Many EVSEs can sit behind one router.", "diff": "Medium", "ai": 3, "grp": "stations-ocpp:78531869"}, {"id": "A3-18", "wk": 7, "n": 18, "topic": "softsw", "type": "mcq", "text": "In the context of PWM full-bridge converters, what is the main purpose of introducing a 'dead time'?", "opts": ["To increase the duty ratio of the switches.", "To reduce the switching frequency.", "To allow device output capacitances to charge/discharge for soft switching and prevent shoot-through.", "To synchronize the leading and lagging legs."], "ans": [2], "exp": "Dead time stops shoot-through and gives the load current time to charge/discharge the switch capacitances so the next switch turns on at zero voltage. It must exceed 2CV<sub>in</sub>/(nI<sub>o</sub>) for the leading leg.", "diff": "Medium", "ai": 3, "grp": "softsw:76433706"}, {"id": "A3-19", "wk": 6, "n": 19, "topic": "dq-control", "type": "mcq", "text": "In the DQ reference frame model of a three-phase AC-DC converter, what must be done to achieve true independent control of the d-axis and q-axis currents?", "opts": ["The switching frequency must be increased.", "The cross-coupling terms (e.g., ωL*Isq) must be compensated for.", "The modulation index must be set to 1.", "The winding resistance (Rs) must be eliminated."], "ans": [1], "exp": "The ωL·i<sub>q</sub> and ωL·i<sub>d</sub> terms couple the axes; feed-forward decoupling compensates them so i<sub>d</sub> and i<sub>q</sub> can be controlled independently.", "diff": "Medium", "ai": 3, "grp": "dq-control:21297880"}, {"id": "A3-20", "wk": 8, "n": 20, "topic": "psfb", "type": "mcq", "text": "In a Phase-Shifted Full Bridge (PSFB) converter, how is the output voltage regulated?", "opts": ["By varying the turn-on time (duty cycle) of all four switches.", "By varying the switching frequency.", "By varying the phase shift between the leading and lagging legs.", "By changing the transformer turns ratio."], "ans": [2], "exp": "Each switch runs at ~50 %; V<sub>o</sub> is set by the phase shift between the leading and lagging legs.", "diff": "Medium", "ai": 3, "grp": "psfb:82461133"}, {"id": "A3-21", "wk": 4, "n": 21, "topic": "dcm-flyback", "type": "mcq", "text": "How does a flyback-based PFC converter operating in Discontinuous Conduction Mode (DCM) achieve unity power factor?", "opts": ["By using a complex current multiplier in its control loop.", "By presenting a resistive input impedance, making the average input current follow the input voltage.", "By operating at a very low switching frequency.", "By ensuring the inductor current is always continuous."], "ans": [1], "exp": "In DCM the flyback looks like a resistor (R<sub>e</sub> = 2L/(d²T<sub>s</sub>)) to the line, so the average input current follows the input voltage automatically.", "diff": "Medium", "ai": 3, "grp": "dcm-flyback:6334550"}, {"id": "A3-22", "wk": 5, "n": 22, "topic": "vsc3", "type": "mcq", "text": "What is a significant advantage of a balanced three-phase AC-DC converter regarding its output capacitor sizing compared to a single-phase converter?", "opts": ["The output voltage is always lower, reducing capacitor voltage stress.", "It requires a capacitor with a higher ESR.", "The second line frequency harmonic component is absent, allowing for a much smaller capacitor.", "It can use a non-polarized capacitor."], "ans": [2], "exp": "p = Σ v<sub>k</sub>i<sub>k</sub>: each phase has a cos(2ωt) term, 120° apart, and they cancel → constant power → no 2f<sub>line</sub> ripple → much smaller capacitor.", "diff": "Medium", "ai": 3, "grp": "vsc3:7659941"}, {"id": "A3-23", "wk": 5, "n": 23, "topic": "vsc3", "type": "mcq", "text": "The RMS current flowing through the DC-link capacitor (I_C_RMS) in a three-phase AC-DC converter is calculated by:", "opts": ["Taking the average of the instantaneous capacitor current over a line cycle.", "Squaring the average converter output current and subtracting it from the square of the RMS converter output current, then taking the square root.", "Multiplying the peak source current by the modulation index.", "Integrating the converter output current over one switching cycle."], "ans": [1], "exp": "The converter DC-side current = DC part (to the load) + AC part (into the capacitor): I<sub>C,rms</sub> = √(I<sub>rms</sub>² − I<sub>avg</sub>²). Lecture result: I<sub>C,rms</sub> = I<sub>s,pk</sub>√((3/π)·M·(5/4) − (9/16)M²) (as printed in the mock key).", "diff": "Hard", "ai": 3, "grp": "vsc3:29477998"}, {"id": "A3-24", "wk": 8, "n": 24, "topic": "psfb", "type": "mcq", "text": "In a Type-2 PWM strategy for a full-bridge converter, why is Zero Voltage Switching (ZVS) turn-on difficult to achieve for the lagging leg switches at light loads?", "opts": ["The dead time for the lagging leg is too short.", "The leading leg switches consume all the available resonant energy.", "The output inductor is short-circuited and does not contribute energy; only the small leakage inductance energy is available for capacitor discharge.", "The body diodes of the lagging leg switches have a high forward voltage drop."], "ans": [2], "exp": "Leading leg: the large output inductor (reflected) keeps the current up → ZVS easy. Lagging leg: secondary shorted by freewheeling rectifiers, only the small leakage energy ½L<sub>lkg</sub>I² is available → ZVS lost at light load.", "diff": "Hard", "ai": 3, "grp": "psfb:28167728"}, {"id": "A3-25", "wk": 9, "n": 25, "topic": "magnetics", "type": "mcq", "text": "In transformer design, what is the relationship between total power loss (P_total), core loss (P_core), copper loss (P_CU_total), and peak AC flux density (∆B)?", "opts": ["Both P_core and P_CU_total increase as ∆B increases.", "P_core increases with ∆B, while P_CU_total decreases with ∆B, resulting in an optimal ∆B for minimum P_total.", "P_core decreases with ∆B, while P_CU_total increases with ∆B.", "Both P_core and P_CU_total are independent of ∆B."], "ans": [1], "exp": "Core loss ∝ ΔB<sup>β</sup> (rises); copper loss ∝ 1/ΔB² (fewer turns needed for larger ΔB, so it falls). Their sum has a minimum at the optimal ΔB.", "diff": "Hard", "ai": 3, "grp": "magnetics:23443473"}, {"id": "A3-26", "wk": 11, "n": 26, "topic": "ccs2", "type": "mcq", "text": "During the SLAC procedure in CCS2 DC charging, what is the purpose of the 'BCB toggle'?", "opts": ["To exchange the Network Membership Key (NMK) between the EV and EVSE.", "To measure the initial signal attenuation across all frequency groups.", "To validate the physical connection by observing a low-frequency voltage change on the CP line when attenuation results are ambiguous.", "To assign an IPv6 address to the EV's communication controller."], "ans": [2], "exp": "If attenuation results are ambiguous, the EV toggles CP between states B and C (BCB toggle); the EVSE that sees the toggle on its own CP line is the one physically connected.", "diff": "Hard", "ai": 3, "grp": "ccs2:86090537"}, {"id": "A3-27", "wk": 3, "n": 27, "topic": "pfc-control", "type": "mcq", "text": "What is a key design criterion for the inner current loop controller (Cc(s)) in a single-phase Boost PFC converter?", "opts": ["It must have a very low gain at DC (s=0).", "Its bandwidth should be higher than the switching frequency.", "It must have a very high gain at twice the line frequency (e.g., 100 Hz) to accurately track the current reference.", "It should be designed to be slower than the outer voltage loop."], "ans": [2], "exp": "Current loop criteria: high gain at 2f<sub>line</sub> so i<sub>L</sub> tracks the 100 Hz rectified-sine reference; bandwidth well below f<sub>sw</sub>; adequate phase/gain margins.", "diff": "Hard", "ai": 3, "grp": "pfc-control:26955929"}, {"id": "A3-28", "wk": 6, "n": 28, "topic": "dq-control", "type": "mcq", "text": "In the closed-loop control design for a three-phase AC-DC converter, how is the proportional gain (KPC) of the inner current loop PI controller typically derived?", "opts": ["By setting it equal to the integral gain (KIC).", "By using pole-zero cancellation and comparing the resulting transfer function to a standard second-order system to achieve a desired damping factor.", "By measuring the phase margin of the open-loop system directly.", "By ensuring the controller's bandwidth is exactly half the switching frequency."], "ans": [1], "exp": "After pole-zero cancellation the loop is compared with a standard second-order system; the desired damping/bandwidth fixes K<sub>PC</sub> (then K<sub>IC</sub> = K<sub>PC</sub>R<sub>s</sub>/L).", "diff": "Hard", "ai": 3, "grp": "dq-control:1161142"}, {"id": "A3-29", "wk": 9, "n": 29, "topic": "magnetics", "type": "mcq", "text": "The core selection for a filter inductor is governed by an inequality relating core geometry to specified electrical parameters. Which geometric property combination is used on the left-hand side of this inequality?", "opts": ["AC * WA / MLT", "AC² * WA / MLT", "AC * WA² / LC", "AC * LC / WA"], "ans": [1], "exp": "Combining L = NΦ/I, B<sub>max</sub>, window fill and winding resistance gives the K<sub>g</sub> condition: A<sub>c</sub>²W<sub>A</sub>/MLT ≥ ρL²I<sub>max</sub>²/(B<sub>max</sub>²Rk<sub>u</sub>).", "diff": "Hard", "ai": 3, "grp": "magnetics:70146118"}, {"id": "A3-30", "wk": 8, "n": 30, "topic": "psfb", "type": "mcq", "text": "In the small signal model of a Phase Shifted Full Bridge (PSFB) converter, how are the DI and DV terms incorporated to account for D-loss?", "opts": ["They are added as parallel resistors in the equivalent circuit.", "They are ignored as they are negligible in the small signal approximation.", "They are used to create additional controlled voltage and current sources that modify the basic buck-derived model.", "They only affect the steady-state operating point, not the small signal model."], "ans": [2], "exp": "Duty loss ΔD = 4L<sub>lkg</sub>I<sub>o</sub>f<sub>s</sub>/(nV<sub>in</sub>) reduces the effective duty and depends on inductor current and input voltage; in the small-signal model its variations (d̃<sub>i</sub>, d̃<sub>v</sub>) appear as extra controlled sources added to the buck-derived model.", "diff": "Hard", "ai": 3, "grp": "psfb:46440401"}, {"id": "A4-1", "wk": 1, "n": 1, "topic": "charger-arch", "type": "mcq", "text": "In an AC charging scenario, where does the primary AC-to-DC power conversion take place?", "opts": ["Within the external AC EVSE unit", "Inside the vehicle's Onboard Charger (OBC)", "At the Central Management System (CMS)", "Directly at the vehicle's battery terminals"], "ans": [1], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Easy", "ai": 4, "grp": "charger-arch:34163027"}, {"id": "A4-2", "wk": 7, "n": 2, "topic": "bridges", "type": "mcq", "text": "What is the primary motivation for operating DC-DC converters at high switching frequencies?", "opts": ["To increase the blocking voltage of the switches", "To reduce the size and weight of passive components like transformers and inductors", "To decrease the converter's output voltage ripple", "To simplify the control loop design"], "ans": [1], "exp": "Higher f<sub>sw</sub> shrinks inductors, capacitors and transformers (less energy/volt-seconds per cycle), at the cost of switching loss.", "diff": "Easy", "ai": 4, "grp": "bridges:97136541"}, {"id": "A4-3", "wk": 5, "n": 3, "topic": "vsc3", "type": "mcq", "text": "What is the primary function of a DC-link capacitor in a three-phase AC-DC converter?", "opts": ["To increase the modulation index", "To smooth the DC voltage and absorb ripple currents", "To generate a high-frequency carrier signal", "To measure the power factor"], "ans": [1], "exp": "The DC-link capacitor holds the DC voltage steady and absorbs the switching-frequency ripple current.", "diff": "Easy", "ai": 4, "grp": "vsc3:93312335"}, {"id": "A4-4", "wk": 2, "n": 4, "topic": "boost-pfc", "type": "mcq", "text": "What does the term \"Unity Power Factor (UPF)\" signify in an AC-DC converter?", "opts": ["The output DC voltage is equal to the input AC voltage.", "The current drawn from the AC source is in phase with the voltage.", "The converter has an efficiency of 100%.", "The switching frequency is equal to the line frequency."], "ans": [1], "exp": "UPF: source current sinusoidal and in phase with the voltage (displacement and distortion both ideal).", "diff": "Easy", "ai": 4, "grp": "boost-pfc:88329068"}, {"id": "A4-5", "wk": 9, "n": 5, "topic": "dab", "type": "mcq", "text": "In the context of the Dual Active Bridge (DAB) converter, what does SPS Modulation stand for?", "opts": ["Secondary Power Switching Modulation", "Symmetrical Pulse Shaping Modulation", "Single Phase Shift Modulation", "Static Power Supply Modulation"], "ans": [2], "exp": "SPS = <b>Single Phase Shift</b>: both bridges at 50 % duty, power set by the phase shift δ between them.", "diff": "Easy", "ai": 4, "grp": "dab:6381953"}, {"id": "A4-6", "wk": 12, "n": 6, "topic": "stations-ocpp", "type": "mcq", "text": "What is the primary purpose of the Open Charge Point Protocol (OCPP)?", "opts": ["To standardize the physical shape of charging connectors", "To regulate the maximum power output of a charging station", "To enable interoperability between EVSEs and Central Management Systems (CMS)", "To define the chemical composition of EV batteries"], "ans": [2], "exp": "OCPP standardises EVSE ↔ CMS communication so any charger works with any back-end (interoperability).", "diff": "Easy", "ai": 4, "grp": "stations-ocpp:14011010"}, {"id": "A4-7", "wk": 4, "n": 7, "topic": "dcm-flyback", "type": "mcq", "text": "What is the defining characteristic of Discontinuous Conduction Mode (DCM) in a PFC converter?", "opts": ["The output voltage is always discontinuous.", "The inductor current falls to zero during each switching cycle.", "The switching frequency is always variable.", "The duty cycle is kept constant at 50%."], "ans": [1], "exp": "DCM: inductor current falls to zero every switching period; the peak follows v<sub>s</sub> automatically, so no multiplier / sine-reference block is needed (simpler control), at the price of higher peak current and THD.", "diff": "Easy", "ai": 4, "grp": "dcm-flyback:4205197"}, {"id": "A4-8", "wk": 7, "n": 8, "topic": "softsw", "type": "mcq", "text": "In a Phase-Shifted Full Bridge (PSFB) converter, what is the purpose of \"dead time\"?", "opts": ["To increase the converter's output power", "To allow for the charging and discharging of switch output capacitances for ZVS", "To measure the transformer's leakage inductance", "To reset the control loop at the end of each cycle"], "ans": [1], "exp": "Dead time stops shoot-through and gives the load current time to charge/discharge the switch capacitances so the next switch turns on at zero voltage. It must exceed 2CV<sub>in</sub>/(nI<sub>o</sub>) for the leading leg.", "diff": "Easy", "ai": 4, "grp": "softsw:76433706"}, {"id": "A4-9", "wk": 4, "n": 9, "topic": "bridgeless", "type": "mcq", "text": "What is the primary advantage of a Totem Pole PFC converter over a conventional boost PFC converter?", "opts": ["It can only operate in Discontinuous Conduction Mode (DCM).", "It has a higher component count.", "It eliminates the input diode bridge, reducing conduction losses.", "It requires a much larger inductor."], "ans": [2], "exp": "The totem pole removes the input diode bridge: 2 devices conduct instead of 3 → lower conduction loss, higher efficiency.", "diff": "Easy", "ai": 4, "grp": "bridgeless:78700125"}, {"id": "A4-10", "wk": 11, "n": 10, "topic": "dc001-can", "type": "mcq", "text": "According to the lecture, what is the dedicated digital communication method used in the BEVC-DC001 standard?", "opts": ["Power Line Communication (PLC)", "Wi-Fi", "Controller Area Network (CAN) Communication", "Bluetooth"], "ans": [2], "exp": "BEVC-DC001 (like GB/T 27930) uses <b>CAN</b> between the EV (BMS) and the charger.", "diff": "Easy", "ai": 4, "grp": "dc001-can:89787655"}, {"id": "A4-11", "wk": 1, "n": 11, "topic": "rectifier", "type": "mcq", "text": "In a single-phase full-bridge rectifier with a resistive load, what is the average DC output voltage (V_d,avg)?", "opts": ["V_s,peak / π", "V_s,peak / 2", "2 * V_s,peak / π", "V_s,peak"], "ans": [2], "exp": "Full-bridge with resistive load: V<sub>d,avg</sub> = 2V<sub>s,peak</sub>/π.", "diff": "Medium", "ai": 4, "grp": "rectifier:61698684"}, {"id": "A4-12", "wk": 12, "n": 12, "topic": "stations-ocpp", "type": "mcq", "text": "What is the primary advantage of using a JSON-based implementation of OCPP (OCPP-J) over a SOAP-based one (OCPP-S)?", "opts": ["It is more secure by default.", "It uses XML, which is more structured.", "It is lightweight, faster, and more scalable due to WebSocket connections.", "It is only compatible with OCPP version 1.6."], "ans": [2], "exp": "OCPP-J (JSON over one persistent WebSocket) is lighter and more scalable than OCPP-S (SOAP/XML over HTTP, which needs the CMS to reach each EVSE by its own address). Many EVSEs can sit behind one router.", "diff": "Medium", "ai": 4, "grp": "stations-ocpp:78531869"}, {"id": "A4-13", "wk": 10, "n": 13, "topic": "ac-type2", "type": "mcq", "text": "In AC Type-2 charging, how does the EV signal to the EVSE that it is ready for charging, causing a transition to State C2?", "opts": ["By sending a high-frequency signal over the PP line.", "By increasing the PWM frequency to 2 kHz.", "By closing its internal S2 switch, which changes the CP line voltage from +9V to +6V.", "By drawing a small amount of current from the L1 pin."], "ans": [2], "exp": "The EV closes S2, adding 1.3 kΩ in parallel; the CP positive level drops from +9 V (B) to +6 V (C). The EVSE sees +6 V and closes its contactor.", "diff": "Medium", "ai": 4, "grp": "ac-type2:22617245"}, {"id": "A4-14", "wk": 9, "n": 14, "topic": "magnetics", "type": "mcq", "text": "What is the primary purpose of introducing an air gap into a filter inductor's core?", "opts": ["To increase the inductance value for the same number of turns.", "To reduce the physical size of the core.", "To increase the saturation current and make the inductance less dependent on core permeability.", "To completely eliminate copper losses."], "ans": [2], "exp": "The gap stores most of the energy and lowers the effective permeability: higher saturation current, inductance set by the gap rather than µ<sub>r</sub>.", "diff": "Medium", "ai": 4, "grp": "magnetics:57947117"}, {"id": "A4-15", "wk": 7, "n": 15, "topic": "bridges", "type": "mcq", "text": "Why is the output ripple frequency in a full-bridge DC-DC converter (2fsw) twice the switching frequency?", "opts": ["Because there are two half-bridges in the converter.", "Because the output inductor current waveform repeats every half switching cycle (Ts/2).", "Because the transformer turns ratio is 2:1.", "Because the output voltage is twice the input voltage."], "ans": [1], "exp": "The secondary rectifier makes the output inductor see the same pulse every half switching period, so the ripple is at 2f<sub>sw</sub> → smaller L and C.", "diff": "Medium", "ai": 4, "grp": "bridges:90890863"}, {"id": "A4-16", "wk": 6, "n": 16, "topic": "dq-control", "type": "mcq", "text": "What is the main advantage of the DQ rotating reference frame for controlling three-phase AC-DC converters?", "opts": ["It increases the switching frequency of the converter.", "It transforms AC quantities into DC quantities under steady-state, simplifying controller design.", "It eliminates the need for an output capacitor.", "It is only applicable to single-phase systems."], "ans": [1], "exp": "In the synchronous dq frame balanced AC quantities become DC in steady state, so simple PI controllers give zero steady-state error.", "diff": "Medium", "ai": 4, "grp": "dq-control:41921964"}, {"id": "A4-17", "wk": 3, "n": 17, "topic": "pfc-stress", "type": "mcq", "text": "In a single-phase boost PFC converter, what is the significance of the \"double line frequency ripple\"?", "opts": ["It improves the power factor of the converter.", "It is a high-frequency ripple that is easy to filter.", "It is a low-frequency ripple (e.g., 100/120 Hz) that necessitates a large output capacitor.", "It only occurs during discontinuous conduction mode."], "ans": [2], "exp": "Single-phase input power = P(1 − cos 2ωt): it pulsates at 2f<sub>line</sub> while the load takes constant P, so the capacitor must absorb a low-frequency (100 Hz) energy swing → large C.", "diff": "Medium", "ai": 4, "grp": "pfc-stress:21437407"}, {"id": "A4-18", "wk": 8, "n": 18, "topic": "psfb", "type": "mcq", "text": "Why is ZVS turn-on for the lagging leg switches in a Type-2 PWM full-bridge converter difficult to achieve at light loads?", "opts": ["The dead time is too long for the lagging leg.", "The leading leg switches consume all the available energy.", "The output inductor is short-circuited, so only the small leakage inductance energy is available for capacitor discharge.", "The lagging leg switches do not have parasitic output capacitances."], "ans": [2], "exp": "Leading leg: the large output inductor (reflected) keeps the current up → ZVS easy. Lagging leg: secondary shorted by freewheeling rectifiers, only the small leakage energy ½L<sub>lkg</sub>I² is available → ZVS lost at light load.", "diff": "Medium", "ai": 4, "grp": "psfb:28167728"}, {"id": "A4-19", "wk": 11, "n": 19, "topic": "ccs2", "type": "mcq", "text": "What is the primary purpose of the Signal Level Attenuation Characterization (SLAC) procedure in CCS2 DC charging?", "opts": ["To measure the battery's state of charge.", "To set the charging voltage and current.", "To logically connect the correct EV and EVSE PLC modems by measuring signal attenuation.", "To perform an insulation check on the charging cable."], "ans": [2], "exp": "SLAC measures signal attenuation from every EVSE modem on the shared cable bundle so the EV joins the one it is physically plugged into (lowest attenuation).", "diff": "Medium", "ai": 4, "grp": "ccs2:3786133"}, {"id": "A4-20", "wk": 1, "n": 20, "topic": "ev-system", "type": "mcq", "text": "In a DC charging scenario, which component acts as the 'master' by dictating the charging profile to the charger?", "opts": ["The Supply Equipment Communication Controller (SECC) in the EVSE", "The vehicle's Onboard Charger (OBC)", "The vehicle's Battery Management System (BMS)", "The Central Management System (CMS) of the charging station"], "ans": [2], "exp": "The <b>BMS is the master</b>: it monitors the cells and requests voltage/current; the charger follows.", "diff": "Medium", "ai": 4, "grp": "ev-system:64286029"}, {"id": "A4-21", "wk": 5, "n": 21, "topic": "vsc3", "type": "mcq", "text": "Why is it advantageous for a balanced three-phase AC-DC converter that its instantaneous input power is constant?", "opts": ["It allows the converter to operate without an inductor.", "It increases the modulation index to above 1.", "It eliminates the second line frequency harmonic component, allowing for a much smaller output capacitor.", "It forces the converter to operate in discontinuous conduction mode."], "ans": [2], "exp": "p = Σ v<sub>k</sub>i<sub>k</sub>: each phase has a cos(2ωt) term, 120° apart, and they cancel → constant power → no 2f<sub>line</sub> ripple → much smaller capacitor.", "diff": "Medium", "ai": 4, "grp": "vsc3:7659941"}, {"id": "A4-22", "wk": 10, "n": 22, "topic": "ac-type2", "type": "mcq", "text": "What is the primary role of the Proximity Pilot (PP) pin in an AC Type-2 charging system?", "opts": ["To carry the main charging current.", "To facilitate PWM-based communication for charging states.", "To provide a ground reference for the vehicle.", "To detect the plug-in and identify the cable's maximum current capacity via resistance R6."], "ans": [3], "exp": "PP: resistor R6 in the plug to PE tells the vehicle a plug is inserted and the cable current rating.", "diff": "Medium", "ai": 4, "grp": "ac-type2:78420395"}, {"id": "A4-23", "wk": 3, "n": 23, "topic": "pfc-control", "type": "mcq", "text": "In the closed-loop control of a single-phase boost PFC converter, why must the inner current loop have a high gain at twice the line frequency (2fs)?", "opts": ["To reject the high-frequency switching ripple.", "To ensure the actual inductor current accurately tracks the 2fs varying reference for unity power factor.", "To slow down the response of the outer voltage loop.", "To reduce the required size of the output capacitor."], "ans": [1], "exp": "Current loop criteria: high gain at 2f<sub>line</sub> so i<sub>L</sub> tracks the 100 Hz rectified-sine reference; bandwidth well below f<sub>sw</sub>; adequate phase/gain margins.", "diff": "Hard", "ai": 4, "grp": "pfc-control:26955929"}, {"id": "A4-24", "wk": 5, "n": 24, "topic": "vsc3", "type": "mcq", "text": "According to the lecture, what is the final derived formula for the RMS current flowing through the DC-link capacitor (I_C_RMS) in a three-phase AC-DC converter?", "opts": ["I_S_peak * √( (3 / π) * M * (5/4) )", "(3/4) * I_S_peak * M", "I_S_peak * √( (3 / π) * M * (5/4) - (9/16) * M^2 )", "I_S_peak * √( (9/16) * M^2 )"], "ans": [2], "exp": "The converter DC-side current = DC part (to the load) + AC part (into the capacitor): I<sub>C,rms</sub> = √(I<sub>rms</sub>² − I<sub>avg</sub>²). Lecture result: I<sub>C,rms</sub> = I<sub>s,pk</sub>√((3/π)·M·(5/4) − (9/16)M²) (as printed in the mock key).", "diff": "Hard", "ai": 4, "grp": "vsc3:29477998"}, {"id": "A4-25", "wk": 11, "n": 25, "topic": "ccs2", "type": "mcq", "text": "In the DC CCS2 charging sequence, what specific condition must be met for the EV's internal disconnecting device (contactors) to close during the pre-charging stage?", "opts": ["The charging current must exceed 2A.", "The isolation resistance must be exactly 100 kΩ.", "The deviation between the EVSE's output voltage and the EV's battery voltage must be less than 20V.", "The EVSE must confirm the connector is locked."], "ans": [2], "exp": "Pre-charge: EVSE raises its output to the battery voltage with current limited to 2 A; the EV closes its contactors only when the difference is below 20 V, so no inrush.", "diff": "Hard", "ai": 4, "grp": "ccs2:74092662"}, {"id": "A4-26", "wk": 9, "n": 26, "topic": "magnetics", "type": "mcq", "text": "During the design of a filter inductor, what is the fundamental inequality derived from the four governing equations that is used for core selection?", "opts": ["AC * WA / MLT ≥ (ρ * L * I_max) / (B_max * R * ku)", "AC² * WA / MLT ≥ (ρ * L² * I_max²) / (B_max² * R * ku)", "AC * WA² / MLT ≥ (ρ * L * I_max) / (B_max * R * ku)", "AC² * WA / LC ≥ (ρ * L² * I_max²) / (B_max² * R * ku)"], "ans": [1], "exp": "Combining L = NΦ/I, B<sub>max</sub>, window fill and winding resistance gives the K<sub>g</sub> condition: A<sub>c</sub>²W<sub>A</sub>/MLT ≥ ρL²I<sub>max</sub>²/(B<sub>max</sub>²Rk<sub>u</sub>).", "diff": "Hard", "ai": 4, "grp": "magnetics:70146118"}, {"id": "A4-27", "wk": 4, "n": 27, "topic": "bridgeless", "type": "mcq", "text": "In a Totem Pole PFC converter, what causes the negative inductor current spike that contributes to zero-crossing distortion?", "opts": ["A delay in the turn-on of switch S4, causing the inductor voltage to become approximately V_o.", "The body diode of S3 conducting for too long.", "When S1 turns on for a short duration while vs is near zero, applying a large negative voltage (vs - V_o) across the inductor.", "The output capacitor discharging back into the inductor."], "ans": [2], "exp": "Near the zero crossing the leg roles swap; if S1 turns on briefly while S4 is on and v<sub>s</sub> ≈ 0, the inductor sees v<sub>s</sub> − V<sub>o</sub> ≈ −V<sub>o</sub> → a steep negative current spike. Switch-timing delays at the crossing cause this zero-crossing distortion.", "diff": "Hard", "ai": 4, "grp": "bridgeless:44859638"}, {"id": "A4-28", "wk": 4, "n": 28, "topic": "dcm-flyback", "type": "mcq", "text": "To guarantee DCM operation in a flyback-based PFC converter under all conditions, the primary inductance L must be selected to be less than the minimum critical inductance (L_critical_min). How is this L_critical_min calculated?", "opts": ["At maximum load resistance (RL_max) and maximum input voltage (Vs,peak_max).", "At minimum load resistance (RL_min) and maximum input voltage (Vs,peak_max).", "At maximum load resistance (RL_max) and minimum input voltage (Vs,peak_min).", "At minimum load resistance (RL_min) and minimum input voltage (Vs,peak_min)."], "ans": [3], "exp": "DCM must hold in the worst case: heaviest load (minimum R<sub>L</sub>) and lowest input voltage give the smallest critical inductance, so L must be below L<sub>crit</sub> evaluated there.", "diff": "Hard", "ai": 4, "grp": "dcm-flyback:65163606"}, {"id": "A4-29", "wk": 6, "n": 29, "topic": "dq-control", "type": "mcq", "text": "In the closed-loop control of a three-phase AC-DC converter, how is the 'K' factor, which links the converter's output current to the d-axis current, derived?", "opts": ["By using pole-zero cancellation in the current loop.", "From the bandwidth of the voltage sensor.", "From the principle of power balance between the three-phase input and the two-phase DQ frame representation.", "By measuring the parasitic inductance of the switches."], "ans": [2], "exp": "K comes from power balance: (3/2)V<sub>sd</sub>I<sub>sd</sub> = V<sub>dc</sub>I<sub>dc</sub> links the d-axis current to the DC-side current.", "diff": "Hard", "ai": 4, "grp": "dq-control:11532925"}, {"id": "A4-30", "wk": 6, "n": 30, "topic": "forward", "type": "mcq", "text": "What is the primary reason a forward converter has limited core utilization compared to a full-bridge converter?", "opts": ["It uses a larger air gap in its transformer core.", "It operates at a much lower switching frequency.", "It only utilizes one quadrant of the transformer's B-H curve (0 to Bmax).", "It requires a lossy reset mechanism."], "ans": [2], "exp": "The forward converter uses only one quadrant of the B-H loop (0 → B<sub>max</sub>) and needs a core-reset mechanism (often lossy) → poor core utilisation, not used at high power.", "diff": "Hard", "ai": 4, "grp": "forward:71958970"}, {"id": "A5-1", "wk": 1, "n": 1, "topic": "charger-arch", "type": "mcq", "text": "What does EVSE stand for?", "opts": ["Electric Vehicle Safety Equipment", "Electric Vehicle Supply Equipment", "Electronic Voltage Source Emitter", "Energy Vehicle Service Enclosure"], "ans": [1], "exp": "EVSE = Electric Vehicle <b>Supply</b> Equipment: the charging station hardware between grid and vehicle.", "diff": "Easy", "ai": 5, "grp": "charger-arch:17264911"}, {"id": "A5-2", "wk": 7, "n": 2, "topic": "softsw", "type": "mcq", "text": "What is Zero Voltage Switching (ZVS)?", "opts": ["A method where the current through the switch is zero before it turns on.", "A method where the voltage across the switch is driven to zero before the current begins to rise during turn-on.", "A technique to eliminate all voltage from the converter circuit.", "A failure mode where the switch voltage drops to zero unexpectedly."], "ans": [1], "exp": "ZVS: the switch voltage is brought to zero (body diode conducting) before its current rises at turn-on, so the turn-on loss is (ideally) zero.", "diff": "Easy", "ai": 5, "grp": "softsw:8745504"}, {"id": "A5-3", "wk": 1, "n": 3, "topic": "rectifier", "type": "mcq", "text": "What is the primary function of a capacitive filter in a rectifier circuit?", "opts": ["To increase the peak input current.", "To store energy and release it during voltage dips, smoothing the DC output.", "To block all DC components from the output.", "To invert the polarity of the AC input."], "ans": [1], "exp": "The filter capacitor stores energy near the peaks and supplies the load in between, smoothing the DC output (at the cost of peaky input current).", "diff": "Easy", "ai": 5, "grp": "rectifier:9433929"}, {"id": "A5-4", "wk": 12, "n": 4, "topic": "stations-ocpp", "type": "mcq", "text": "What does OCPP stand for?", "opts": ["Open Circuit Power Protocol", "Optimal Charging Point Protocol", "Open Charge Point Protocol", "Official Charger Port Protocol"], "ans": [2], "exp": "OCPP = <b>Open Charge Point Protocol</b>: EVSE ↔ central management system.", "diff": "Easy", "ai": 5, "grp": "stations-ocpp:21692550"}, {"id": "A5-5", "wk": 10, "n": 5, "topic": "ac-type2", "type": "mcq", "text": "In AC Type-2 charging, what method is used for communication on the Control Pilot (CP) line?", "opts": ["CAN bus communication", "Power Line Communication (PLC)", "Pulse Width Modulation (PWM) signaling", "Ethernet communication"], "ans": [2], "exp": "AC Type-2 uses low-level PWM signalling on CP (SAE J1772 / IEC 61851): duty = current limit, voltage level = state.", "diff": "Easy", "ai": 5, "grp": "ac-type2:45923605"}, {"id": "A5-6", "wk": 9, "n": 6, "topic": "magnetics", "type": "mcq", "text": "What is the primary purpose of introducing an air gap into the core of a filter inductor?", "opts": ["To increase the core's permeability.", "To make the inductor lighter.", "To prevent core saturation and increase the saturation current.", "To maximize core losses for thermal management."], "ans": [2], "exp": "The gap stores most of the energy and lowers the effective permeability: higher saturation current, inductance set by the gap rather than µ<sub>r</sub>.", "diff": "Easy", "ai": 5, "grp": "magnetics:57947117"}, {"id": "A5-7", "wk": 4, "n": 7, "topic": "bridgeless", "type": "mcq", "text": "What is the primary advantage of a Totem Pole PFC converter over a traditional boost PFC?", "opts": ["It can only operate in Discontinuous Conduction Mode.", "It eliminates the input diode bridge, reducing conduction losses and improving efficiency.", "It requires a much larger inductor for the same power level.", "It operates at a lower output voltage."], "ans": [1], "exp": "The totem pole removes the input diode bridge: 2 devices conduct instead of 3 → lower conduction loss, higher efficiency.", "diff": "Easy", "ai": 5, "grp": "bridgeless:78700125"}, {"id": "A5-8", "wk": 1, "n": 8, "topic": "charger-arch", "type": "mcq", "text": "In an AC charging system, where does the conversion from AC to DC power take place?", "opts": ["Inside the AC EVSE (charging station).", "Within the charging cable itself.", "At the grid substation.", "Inside the vehicle, within the Onboard Charger (OBC)."], "ans": [3], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Easy", "ai": 5, "grp": "charger-arch:34163027"}, {"id": "A5-9", "wk": 7, "n": 9, "topic": "softsw", "type": "mcq", "text": "What is the purpose of \"dead time\" in a half-bridge converter leg?", "opts": ["To increase switching losses for better thermal performance.", "A period where the converter is completely powered down for safety.", "An intentional delay to prevent shoot-through and enable soft switching.", "The time it takes for the inductor current to reach zero."], "ans": [2], "exp": "Dead time stops shoot-through and gives the load current time to charge/discharge the switch capacitances so the next switch turns on at zero voltage. It must exceed 2CV<sub>in</sub>/(nI<sub>o</sub>) for the leading leg.", "diff": "Easy", "ai": 5, "grp": "softsw:76433706"}, {"id": "A5-10", "wk": 11, "n": 10, "topic": "dc001-can", "type": "mcq", "text": "What communication protocol is exclusively used for data exchange between the EV and EVSE in the BEVC-DC001 standard?", "opts": ["Power Line Communication (PLC)", "Ethernet", "Controlled Area Network (CAN)", "Pulse Width Modulation (PWM)"], "ans": [2], "exp": "BEVC-DC001 (like GB/T 27930) uses <b>CAN</b> between the EV (BMS) and the charger.", "diff": "Easy", "ai": 5, "grp": "dc001-can:89787655"}, {"id": "A5-11", "wk": 1, "n": 11, "topic": "charger-arch", "type": "mcq", "text": "What is the primary difference between AC and DC charging in terms of power conversion location?", "opts": ["AC charging converts power at the grid, while DC charging converts it in the vehicle.", "AC charging converts AC to DC inside the vehicle (onboard), while DC charging converts it outside the vehicle (off-board).", "Both AC and DC charging convert power inside the vehicle, but at different speeds.", "DC charging uses AC power directly, while AC charging requires an initial DC conversion."], "ans": [1], "exp": "AC charging: conversion in the on-board charger (vehicle). DC charging: conversion off-board in the DC EVSE, which feeds the battery directly.", "diff": "Medium", "ai": 5, "grp": "charger-arch:34163027"}, {"id": "A5-12", "wk": 5, "n": 12, "topic": "vsc3", "type": "mcq", "text": "Why is the simplified power balance approach inadequate for sizing the DC-link capacitor in a three-phase AC-DC converter?", "opts": ["It overestimates the required capacitance by a factor of three.", "It only works for single-phase converters.", "It neglects the impact of high-frequency switching harmonics which cause ripple currents in the capacitor.", "It assumes the input power is always constant, which is incorrect."], "ans": [2], "exp": "In a balanced 3-φ converter the power balance gives no low-frequency ripple, so the capacitor current is set by switching-frequency harmonics; the capacitor must be sized from its RMS ripple current instead.", "diff": "Medium", "ai": 5, "grp": "vsc3:38181018"}, {"id": "A5-13", "wk": 7, "n": 13, "topic": "bridges", "type": "mcq", "text": "What is the main difference in the primary voltage applied to the transformer between a full-bridge and a half-bridge converter?", "opts": ["The full-bridge applies the full input voltage (Vin), while the half-bridge applies half the input voltage (Vin/2).", "The full-bridge applies a sinusoidal voltage, while the half-bridge applies a square wave voltage.", "The full-bridge applies Vin/2, while the half-bridge applies the full Vin.", "There is no difference; both apply the full input voltage Vin."], "ans": [0], "exp": "Full bridge applies ±V<sub>in</sub> to the primary; half bridge only ±V<sub>in</sub>/2.", "diff": "Medium", "ai": 5, "grp": "bridges:68402703"}, {"id": "A5-14", "wk": 6, "n": 14, "topic": "dq-control", "type": "mcq", "text": "What is the significance of the cross-coupling terms (e.g., ω * L * Isq) in the DQ axis model of a three-phase converter?", "opts": ["They represent the power losses in the converter.", "They indicate that the d-axis and q-axis are inherently independent.", "They link the d-axis and q-axis dynamics, and must be compensated for to achieve true independent control.", "They are artifacts of the transformation and can be ignored in the control design."], "ans": [2], "exp": "The ωL·i<sub>q</sub> and ωL·i<sub>d</sub> terms couple the axes; feed-forward decoupling compensates them so i<sub>d</sub> and i<sub>q</sub> can be controlled independently.", "diff": "Medium", "ai": 5, "grp": "dq-control:21297880"}, {"id": "A5-15", "wk": 8, "n": 15, "topic": "psfb", "type": "mcq", "text": "What is the impact of the \"D-loss\" term on the effective duty cycle of a PSFB converter?", "opts": ["It increases the effective duty cycle, leading to a higher output voltage.", "It has no impact on the effective duty cycle, only on the losses.", "It reduces the effective duty cycle, and this reduction varies with inductor current and input voltage.", "It is a constant loss term that only affects efficiency."], "ans": [2], "exp": "Duty loss ΔD = 4L<sub>lkg</sub>I<sub>o</sub>f<sub>s</sub>/(nV<sub>in</sub>) reduces the effective duty and depends on inductor current and input voltage; in the small-signal model its variations (d̃<sub>i</sub>, d̃<sub>v</sub>) appear as extra controlled sources added to the buck-derived model.", "diff": "Medium", "ai": 5, "grp": "psfb:46440401"}, {"id": "A5-16", "wk": 10, "n": 16, "topic": "ac-type2", "type": "mcq", "text": "How does the EV signal its readiness for charging to the EVSE in an AC Type-2 system?", "opts": ["By sending a high-frequency signal over the power lines.", "By changing the PWM duty ratio on the CP line.", "By changing the voltage level of the PWM signal on the CP line (e.g., from +9V to +6V).", "By changing the resistance on the PP pin."], "ans": [2], "exp": "The EV closes S2, adding 1.3 kΩ in parallel; the CP positive level drops from +9 V (B) to +6 V (C). The EVSE sees +6 V and closes its contactor.", "diff": "Medium", "ai": 5, "grp": "ac-type2:22617245"}, {"id": "A5-17", "wk": 9, "n": 17, "topic": "magnetics", "type": "mcq", "text": "Why are core losses often considered negligible in the design of filter inductors for DC-DC converters?", "opts": ["Filter inductors use cores that have no magnetic properties.", "The large DC bias current completely eliminates the BH loop.", "The AC ripple current is typically very small, resulting in a very small BH loop area and thus minimal core loss.", "The air gap in the core redirects all magnetic flux, preventing any core losses."], "ans": [2], "exp": "A filter inductor carries mostly DC with a small ripple, so the minor B-H loop is tiny and core loss is small.", "diff": "Medium", "ai": 5, "grp": "magnetics:23475367"}, {"id": "A5-18", "wk": 3, "n": 18, "topic": "pfc-control", "type": "mcq", "text": "What is the purpose of the saturation block in the voltage control loop of a boost PFC converter?", "opts": ["To saturate the inductor core for faster response.", "To limit the output voltage to a safe level.", "To limit the output of the voltage controller, thereby limiting the maximum current demand to protect components.", "To ensure the voltage controller's output is always a sinusoidal waveform."], "ans": [2], "exp": "The saturation (limiter) on the voltage-controller output caps the current reference amplitude, limiting peak inductor/switch current during start-up and load steps.", "diff": "Medium", "ai": 5, "grp": "pfc-control:89800691"}, {"id": "A5-19", "wk": 4, "n": 19, "topic": "dcm-flyback", "type": "mcq", "text": "What is the main advantage of operating a boost PFC converter in DCM regarding the control strategy?", "opts": ["It allows for higher power transfer than CCM.", "It completely eliminates Total Harmonic Distortion (THD).", "It simplifies control by eliminating the need for a multiplier block and unit sine wave generation.", "It requires a much smaller output capacitor."], "ans": [2], "exp": "DCM: inductor current falls to zero every switching period; the peak follows v<sub>s</sub> automatically, so no multiplier / sine-reference block is needed (simpler control), at the price of higher peak current and THD.", "diff": "Medium", "ai": 5, "grp": "dcm-flyback:4205197"}, {"id": "A5-20", "wk": 12, "n": 20, "topic": "stations-ocpp", "type": "mcq", "text": "What is the key advantage of using JSON over WebSocket compared to SOAP for OCPP communication in terms of scalability?", "opts": ["JSON messages are encrypted by default, while SOAP messages are not.", "A persistent WebSocket connection allows multiple EVSEs to be behind a single router without needing unique IP addresses for each.", "SOAP can only handle a single EVSE per CMS.", "JSON uses less electricity for data transmission."], "ans": [1], "exp": "OCPP-J (JSON over one persistent WebSocket) is lighter and more scalable than OCPP-S (SOAP/XML over HTTP, which needs the CMS to reach each EVSE by its own address). Many EVSEs can sit behind one router.", "diff": "Medium", "ai": 5, "grp": "stations-ocpp:78531869"}, {"id": "A5-21", "wk": 1, "n": 21, "topic": "ev-system", "type": "mcq", "text": "In a DC charging scenario, what is the role of the vehicle's Battery Management System (BMS)?", "opts": ["It acts as a slave, only receiving commands from the DC EVSE.", "It is bypassed and has no role in DC charging.", "It acts as the master, monitoring battery parameters and dictating the required charging profile to the DC EVSE.", "Its only role is to control the vehicle's onboard charger."], "ans": [2], "exp": "The <b>BMS is the master</b>: it monitors the cells and requests voltage/current; the charger follows.", "diff": "Medium", "ai": 5, "grp": "ev-system:64286029"}, {"id": "A5-22", "wk": 11, "n": 22, "topic": "ccs2", "type": "mcq", "text": "What is the purpose of the pre-charging stage in the DC CCS2 charging sequence?", "opts": ["To test the maximum current the cable can handle.", "To gradually raise the EVSE output voltage to match the battery voltage, preventing large inrush currents.", "To fully charge the EVSE's internal capacitors before power transfer.", "To allow the user to select the desired charging speed."], "ans": [1], "exp": "Pre-charge: EVSE raises its output to the battery voltage with current limited to 2 A; the EV closes its contactors only when the difference is below 20 V, so no inrush.", "diff": "Medium", "ai": 5, "grp": "ccs2:74092662"}, {"id": "A5-23", "wk": 5, "n": 23, "topic": "vsc3", "type": "mcq", "text": "According to the lecture, the RMS current through the DC-link capacitor (I_C_RMS) is calculated using the formula √(I_converter_RMS_Line^2 - I_converter_avg_Line^2). What does this relationship signify?", "opts": ["The capacitor current is the sum of the average and RMS converter currents.", "The RMS capacitor current is the portion of the total RMS converter current that does not flow to the load, representing the ripple component.", "The capacitor current is always equal to the average load current.", "This formula calculates the peak capacitor current, not the RMS value."], "ans": [1], "exp": "The converter DC-side current = DC part (to the load) + AC part (into the capacitor): I<sub>C,rms</sub> = √(I<sub>rms</sub>² − I<sub>avg</sub>²). Lecture result: I<sub>C,rms</sub> = I<sub>s,pk</sub>√((3/π)·M·(5/4) − (9/16)M²) (as printed in the mock key).", "diff": "Hard", "ai": 5, "grp": "vsc3:29477998"}, {"id": "A5-24", "wk": 9, "n": 24, "topic": "magnetics", "type": "mcq", "text": "In the iterative transformer design procedure, what is the immediate next step if the calculated total loss (P_total) exceeds the allowed total loss (P_total_allowed)?", "opts": ["Increase the switching frequency to reduce core size.", "Select a smaller wire gauge to fit more turns in the window area.", "Go back to Step 1 and select the next bigger core size.", "Increase the peak AC flux density (deltaB) to reduce copper losses."], "ans": [2], "exp": "If the minimum achievable loss of the chosen core is still above the allowed loss, pick the next bigger core and repeat.", "diff": "Hard", "ai": 5, "grp": "magnetics:16892204"}, {"id": "A5-25", "wk": 7, "n": 25, "topic": "bridges", "type": "mcq", "text": "Why does the output inductor and capacitor in a full-bridge converter experience a ripple frequency of 2fsw?", "opts": ["Because the transformer has two windings, doubling the frequency.", "Because the full-bridge rectifier on the secondary side inverts the negative half-cycles, causing the inductor current to repeat its pattern every half switching cycle (Ts/2).", "It is an error in the analysis; the ripple frequency is always fsw.", "Because there are four switches, and each one contributes to the ripple."], "ans": [1], "exp": "The secondary rectifier makes the output inductor see the same pulse every half switching period, so the ripple is at 2f<sub>sw</sub> → smaller L and C.", "diff": "Hard", "ai": 5, "grp": "bridges:90890863"}, {"id": "A5-26", "wk": 8, "n": 26, "topic": "psfb", "type": "mcq", "text": "In the small signal model for a PSFB converter, how are the DI and DV terms, which account for D-loss variation, incorporated into the equivalent circuit?", "opts": ["They are ignored as they are second-order effects.", "They are added as additional series resistors in the inductor path.", "They are represented by additional controlled voltage and current sources that modify the basic buck converter model.", "They only affect the steady-state DC operating point, not the small signal model."], "ans": [2], "exp": "Duty loss ΔD = 4L<sub>lkg</sub>I<sub>o</sub>f<sub>s</sub>/(nV<sub>in</sub>) reduces the effective duty and depends on inductor current and input voltage; in the small-signal model its variations (d̃<sub>i</sub>, d̃<sub>v</sub>) appear as extra controlled sources added to the buck-derived model.", "diff": "Hard", "ai": 5, "grp": "psfb:46440401"}, {"id": "A5-27", "wk": 4, "n": 27, "topic": "dcm-flyback", "type": "mcq", "text": "Why does DCM operation in a boost PFC converter typically result in a higher Total Harmonic Distortion (THD) compared to CCM operation?", "opts": ["Because the switching frequency in DCM is much lower.", "Because the average input current, while following the voltage shape, is not perfectly sinusoidal due to the triangular nature of the inductor current pulses.", "Because DCM operation requires a larger inductor, which introduces more distortion.", "Because the output voltage ripple is higher in DCM, which reflects back to the input current."], "ans": [1], "exp": "In DCM the average of the triangular inductor-current pulses is not exactly proportional to v<sub>s</sub>, so the input current is slightly distorted → higher THD than CCM.", "diff": "Hard", "ai": 5, "grp": "dcm-flyback:67846538"}, {"id": "A5-28", "wk": 8, "n": 28, "topic": "psfb", "type": "mcq", "text": "In Type-2 PWM for a full-bridge converter, why is ZVS turn-on reliably achieved for the leading leg switches but challenging for the lagging leg switches?", "opts": ["The leading leg switches operate at a lower frequency.", "The lagging leg switches have much larger output capacitances.", "The leading leg uses energy from the large output inductor for ZVS, while the lagging leg only has the smaller leakage inductance energy available.", "The leading leg switches are made of a different material (e.g., GaN) that switches faster."], "ans": [2], "exp": "Leading leg: the large output inductor (reflected) keeps the current up → ZVS easy. Lagging leg: secondary shorted by freewheeling rectifiers, only the small leakage energy ½L<sub>lkg</sub>I² is available → ZVS lost at light load.", "diff": "Hard", "ai": 5, "grp": "psfb:28167728"}, {"id": "A5-29", "wk": 9, "n": 29, "topic": "dab", "type": "mcq", "text": "In Single Phase Shift (SPS) modulation for a DAB converter, why is it crucial to maintain a symmetrical inductor current waveform?", "opts": ["To ensure the output voltage is always positive.", "To maximize the power transfer at all times.", "To prevent a DC offset in the transformer primary current, which could lead to flux walking and core saturation.", "To simplify the calculation of RMS current."], "ans": [2], "exp": "An asymmetric current means a DC offset in the transformer current → flux walking → core saturation.", "diff": "Hard", "ai": 5, "grp": "dab:78928212"}, {"id": "A5-30", "wk": 5, "n": 30, "topic": "vsc3", "type": "mcq", "text": "In a balanced three-phase AC-DC converter operating at unity power factor, why is the instantaneous input power constant?", "opts": ["Because the three-phase voltages and currents are always constant.", "Because the sum of the three phase powers, each containing a cos(2ωt) term phase-shifted by 120°, results in the cancellation of all time-varying components.", "Because the output capacitor perfectly smooths the input power.", "This is an incorrect assumption; the input power always pulsates at twice the line frequency."], "ans": [1], "exp": "p = Σ v<sub>k</sub>i<sub>k</sub>: each phase has a cos(2ωt) term, 120° apart, and they cancel → constant power → no 2f<sub>line</sub> ripple → much smaller capacitor.", "diff": "Hard", "ai": 5, "grp": "vsc3:7659941"}];
